   l_sig.title := 'Recommended Framework  Patches';
   l_sig.fail_condition := '[Applied] = [No]';
   l_sig.problem_descr := 'There are recommended Framework patch(es) not applied to this '||mask_text(g_apps_version, nvl( upper(''), 'NO_MASK') )||' environment. <br>Please expand the list above for the details.';
   l_sig.solution := 'Above are the recommended Framework Codelevel ['||mask_text(g_fwk_level, nvl( upper(''), 'NO_MASK') )||'] patches for this '||mask_text(g_apps_version, nvl( upper(''), 'NO_MASK') )||' instance '||mask_text(g_instance, nvl( upper(''), 'NO_MASK') )||'.<br><br> 

For the most current recommended Framework patches, use [2300940/KB163512] - How to Identify what is the Framework Bundle Level Applied in 12.1 and 12.2 Installations.<br><br> For the most current EBS recommended patches, use Patch Wizard or the Updates & Patches Tab in My Oracle Support.<br> 
Further guidance can be found in the following documents: 
<ul> 
<li>[11086538/KA747] How to Find EBS Patches and EBS Technology Patches</li>
<li>[976188/KB739927] Patch Wizard Utility</li> <li>[10940175/KA580] Patch Wizard FAQ</li> 
</ul>';
   l_sig.success_msg := 'Congratulations!!<br> 
The latest recommended Framework Codelevel ['||mask_text(g_fwk_level, nvl( upper(''), 'NO_MASK') )||'] patches for this '||mask_text(g_apps_version, nvl( upper(''), 'NO_MASK') )||' instance '||mask_text(g_instance, nvl( upper(''), 'NO_MASK') )||' have been applied.<br><br>';
   l_sig.print_condition := 'ALWAYS';
   l_sig.fail_type := 'W';
   l_sig.print_sql_output := 'Y';
   l_sig.limit_rows := 'N';
   l_sig.extra_info := l_extra_info;
   l_sig.include_in_xml :='P';
   l_sig.version := '26';

   -- if snapshot is old, add message to the solution
   IF nvl(g_snap_days, 10) > 30 THEN
       l_sig.solution := l_sig.solution || '<br><br><b>ADADMIN</b>: Maintain Snapshot Information was executed more than 30 days ago.<br>It is recommended that AD Utilities (Adadmin) "Maintain Snapshot Information" is run periodically as key tools (Patch Wizard, ADPatch,etc) rely on this information being accurate and up-to-date.';
   END IF;

  -- Check if applied
  get_current_time(g_query_start_time);
  FOR i in 1..l_rows loop
    l_step := '40';
    OPEN get_app_date(l_col_rows(1)(i),l_rel_rows(1)(i));
    FETCH get_app_date INTO l_app_date;
    CLOSE get_app_date;
    l_col_rows(1)(i) := '{'||l_col_rows(1)(i)||'}';
    IF l_app_date is not null THEN
      l_step := '50';
      l_col_rows(2)(i) := 'Yes';
      l_col_rows(3)(i) := to_char(l_app_date);
    END IF;
  END LOOP;
  g_query_elapsed := stop_timer(g_query_start_time);
  debug(' Rows fetched: '||to_char(l_rows));

  -- Register
  l_step := '60';
  g_signatures('FWK_C5') := l_sig;

  --Render
  l_step := '70';
  RETURN process_signature_results(
    'FWK_C5',     -- sig ID
    l_sig,                              -- signature information
    l_col_rows,                         -- data
    l_hdr);                             -- headers

EXCEPTION WHEN OTHERS THEN
  print_log('Error in check_rec_patches_9 at step '||l_step);
  raise;
END check_rec_patches_9;

