----------------------------------------------------------------
--- Validate Parameters                                      ---
----------------------------------------------------------------
PROCEDURE validate_parameters(
            p_org_id                       IN NUMBER      DEFAULT NULL
           ,p_doc_type                     IN VARCHAR2    DEFAULT NULL
           ,p_doc_number                   IN VARCHAR2    DEFAULT NULL
           ,p_doc_release                  IN NUMBER      DEFAULT NULL
           ,p_req_line_number              IN NUMBER      DEFAULT NULL
           ,p_po_line_number               IN NUMBER      DEFAULT NULL
           ,p_bpa_line_number              IN NUMBER      DEFAULT NULL
           ,p_rel_line_number              IN NUMBER      DEFAULT NULL
           ,p_include_apps_check           IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 200
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

IS

  l_revision                  VARCHAR2(25);
  l_date_char                 VARCHAR2(30);
  l_instance                  VARCHAR2(255);
  l_apps_version              VARCHAR2(255);
  l_host                      VARCHAR2(255);
  l_full_hostname             VARCHAR2(255);
  l_key                       VARCHAR2(255);
  l_system_function_var       VARCHAR2(2000);
  l_exists_val                VARCHAR2(2000);
  l_index                     NUMBER:=1;
  l_dbversion                 VARCHAR2(255);
  l_db_name                   VARCHAR2(255);
  l_step                      VARCHAR2(10);
  invalid_parameters EXCEPTION;
  invalid_escape EXCEPTION;

----------------------------------------------------------------
-- Analyzer-specific code: Validation Declarations            --
----------------------------------------------------------------
  l_doc_id NUMBER;
  l_sob_id NUMBER;
  l_legal_entity_id NUMBER;
  l_release_id NUMBER;
  l_trx_type       VARCHAR2(20);
  l_doc_subtype    VARCHAR2(25);
  l_preparer_id    NUMBER;
  l_app_path_id    NUMBER;
  l_created_by     NUMBER;
  l_from_date      VARCHAR2(25);
  l_item_type      WF_ITEMS.ITEM_TYPE%TYPE;
  l_item_key       WF_ITEMS.ITEM_KEY%TYPE;
  l_run_date       VARCHAR2(30);
  l_date           DATE;
  l_counter        NUMBER;
  l_sql            VARCHAR2(4000);
  l_style_id       NUMBER;  
  l_backing_req    VARCHAR2(1) := NULL; 
  l_assoc_po       VARCHAR2(1) := NULL;
  l_line_id        NUMBER;
  l_dest_expense     VARCHAR2(1)  := 'N';
  l_dest_inventory   VARCHAR2(1)  := 'N';
  l_dest_inventory_rel    VARCHAR2(1)  := 'N'; 
  l_int_req    VARCHAR2(1)  := 'N';
  l_responsibility_name       VARCHAR2(100); 
  l_user_name                 VARCHAR2(100); 
  l_drop_ship    VARCHAR2(1)  := 'N';
  l_po_release_id NUMBER;
  l_DBbanner    VARCHAR2(255);
  l_fwk_level          VARCHAR2(5);



FUNCTION get_DOCTYPESHORT
   return VARCHAR2 IS
BEGIN
debug('begin sql token function: DOCTYPESHORT');
  IF (l_trx_type = 'BPA') THEN
      return 'PO';
  ELSIF (l_trx_type = 'REL') THEN
      return 'RELEASE';
  ELSE
      return l_trx_type;
  END IF;  
debug('end sql token function: DOCTYPESHORT');
END get_DOCTYPESHORT;



BEGIN

  l_step := '1';

  print_log(analyzer_title || ' Log File');
  print_log('***************************************************************');

  -- Create global hash for parameters. Numbers required for the output order
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Unit';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Document Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_doc_type,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Document Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_doc_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Release Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_doc_release,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Requisition Line Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_req_line_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'PO Line Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_po_line_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'BPA Line Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_bpa_line_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Release Shipment Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_rel_line_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Diagnostic Apps Check';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_include_apps_check,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  print_log(chr(10)||'Parameter Values before validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  BEGIN

    SELECT max(release_name) INTO l_apps_version
    FROM fnd_product_groups;

    begin
        -- Try to get version using new 19c method
        execute immediate 'select instance_name, host_name, version_full, sys_context(''USERENV'',''DB_NAME'') FROM v$instance'
            into l_instance, l_host, l_dbversion, l_db_name;
    exception when others then
        -- Get version using old method
        SELECT instance_name, host_name, version, sys_context('USERENV','DB_NAME')
        INTO l_instance, l_host, l_dbversion, l_db_name
        FROM v$instance;
    end;
    l_host := nvl(l_host, sys_context('USERENV','SERVER_HOST'));
    l_instance := nvl(l_instance, sys_context('USERENV','INSTANCE_NAME'));

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters gathering instance information: '
      ||sqlerrm);
    raise;
  END;

  l_step := '2';
  BEGIN
    SELECT distinct domain
    INTO l_full_hostname
    FROM (SELECT db_domain AS domain
            FROM fnd_databases
          UNION ALL
          SELECT domain AS domain
          FROM fnd_nodes) domains WHERE domains.domain IS NOT NULL and rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_full_hostname := NULL;
        WHEN OTHERS    THEN
          print_log('Error in validate_parameters gathering instance information: '
          ||sqlerrm);
    END;

  l_step := '3';
-- Revision and date values can be populated by RCS
  l_revision := rtrim(replace('$Revision: 200.55  $','$',''));
  l_revision := ltrim(replace(l_revision,'Revision:',''));
  l_date_char := rtrim(replace('$Date: 2026/01/27 20:11:53 $','$',''));
  l_date_char := ltrim(replace(l_date_char,'Date:',''));
  l_date_char := to_char(to_date(l_date_char,'YYYY/MM/DD HH24:MI:SS'),'DD-MON-YYYY');

  l_step := '4';
-- Create global hash for mapping internal result codes (E, W, S, I) to user friendly result codes (error, warning, successful, information)
  g_result('E') := 'error';
  g_result('W') := 'warning';
  g_result('S') := 'success';
  g_result('I') := 'info';

  l_step := '5';
-- Create global hash for report information
-- Do not report host details (EBSAF-274); reverted by EBSAF-293
  g_rep_info('Host') := regexp_substr(l_host, '^[^.]+');
  -- the host name might already be fully qualified, need to check if it includes the domain before appending it
  IF (l_host LIKE '%.%') THEN
       g_rep_info('FullHost') := l_host;
  ELSE
       g_rep_info('FullHost') := l_host || '.' || l_full_hostname;
  END IF;
  l_step := '6';
  g_rep_info('Instance') := l_instance;
  g_rep_info('DB Name') := l_db_name;
  g_rep_info('DB Version') := l_dbversion;
  g_rep_info('Apps Version') := l_apps_version;
  g_rep_info('File Name') := 'po_doc_analyzer.sql';
  g_rep_info('File Version') := l_revision;
  g_rep_info('Framework Version') := RTRIM(g_framework_version, ' ');
  g_rep_info('Execution Date') := to_char(sysdate,'DD-MON-YYYY HH24:MI:SS');
  g_rep_info('Description') := ('The ' || analyzer_title || ' <a href="' || g_cmos_km_url || g_analyzer_doc_id||'" target="_blank">(Note '||g_analyzer_doc_id||')</a> is a self-service health-check script that reviews the overall footprint, analyzes current configurations and settings for the environment and provides feedback and recommendations on best practices. Your application data is not altered in any way when you run this analyzer.');

  l_step := '7';
  IF (g_is_concurrent) THEN
     populate_user_details();
  END IF;

  ------------------------------------------------------------------------------
  -- NOTE: Add code here for validation to the parameters of your diagnostic
  ------------------------------------------------------------------------------
  l_step := '8';


  g_max_output_rows := nvl(p_max_output_rows,20);
  g_debug_mode := nvl(p_debug_mode, 'Y');

debug('begin parameter validation: p_org_id');
IF p_org_id IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Operating Unit is required.');
   raise invalid_parameters;
END IF;
IF p_org_id IS NOT NULL THEN
BEGIN
SELECT U.ORGANIZATION_ID
INTO l_exists_val
FROM HR_OPERATING_UNITS U
WHERE U.ORGANIZATION_ID = p_org_id
 AND mo_global.is_mo_init_done = 'N' or mo_global.check_access(U.ORGANIZATION_ID) = 'Y'
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT:  No operating unit organization ID specified.
The org_id parameter is mandatory.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_org_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_org_id');

debug('begin parameter validation: p_doc_type');
IF p_doc_type IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Document Type is required.');
   raise invalid_parameters;
END IF;
IF p_doc_type IS NOT NULL AND p_doc_type NOT IN ( 'BPA','PO','QUOTATION','REL','REQ','RFQ') THEN
   print_error('INVALID ARGUMENT: This document type is invalid!');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_doc_type');

debug('begin parameter validation: p_doc_number');
IF p_doc_number IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Document Number is required.');
   raise invalid_parameters;
END IF;
IF p_doc_number IS NOT NULL THEN
BEGIN
SELECT SEGMENT1
INTO l_exists_val
FROM (SELECT SEGMENT1 FROM PO_HEADERS_ALL WHERE ORG_ID = P_ORG_ID AND P_DOC_TYPE <> 'REQ' UNION ALL SELECT SEGMENT1 FROM PO_REQUISITION_HEADERS_ALL WHERE ORG_ID = P_ORG_ID AND P_DOC_TYPE = 'REQ')
WHERE SEGMENT1 = p_doc_number and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid document number specified!');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_doc_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_doc_number');

debug('begin parameter validation: p_doc_release');
IF p_doc_release IS NOT NULL THEN
BEGIN
SELECT R.RELEASE_NUM
INTO l_exists_val
FROM PO_RELEASES_ALL R, PO_HEADERS_ALL H
WHERE R.RELEASE_NUM = p_doc_release
 AND r.po_header_id = h.po_header_id 
and p_doc_type = 'REL' 
and h.segment1 = p_doc_number
and h.org_id = p_org_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid release, PO and org_id combination.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_doc_release failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_doc_release');

debug('begin parameter validation: p_req_line_number');
IF p_req_line_number IS NOT NULL THEN
BEGIN
SELECT RL.LINE_NUM
INTO l_exists_val
FROM PO_REQUISITION_LINES_ALL RL, PO_REQUISITION_HEADERS_ALL RH
WHERE RL.LINE_NUM = p_req_line_number
 AND rh.segment1=p_doc_number and rh.requisition_header_id = rl.requisition_header_id and rh.org_id = p_org_id and p_doc_type = 'REQ'
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Requisition line number is incorrect for the document provided!');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_req_line_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_req_line_number');

debug('begin parameter validation: p_po_line_number');
IF p_po_line_number IS NOT NULL THEN
BEGIN
SELECT POL.LINE_NUM
INTO l_exists_val
FROM PO_LINES_ALL POL, PO_HEADERS_ALL POH
WHERE POL.LINE_NUM = p_po_line_number
 AND poh.segment1 = p_doc_number and poh.org_id = p_org_id and poh.po_header_id = pol.po_header_id and p_doc_type = 'PO' and poh.type_lookup_code in ('PLANNED', 'STANDARD')
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Line number if incorrect for the selected document!');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_po_line_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_po_line_number');

debug('begin parameter validation: p_bpa_line_number');
IF p_bpa_line_number IS NOT NULL THEN
BEGIN
SELECT POL.LINE_NUM
INTO l_exists_val
FROM PO_LINES_ALL POL, PO_HEADERS_ALL POH
WHERE POL.LINE_NUM = p_bpa_line_number
 AND poh.segment1 = p_doc_number and poh.org_id = p_org_id and poh.po_header_id = pol.po_header_id and p_doc_type = 'BPA' and poh.type_lookup_code in ('BLANKET')
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: The BPA Line Number is invalid!');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_bpa_line_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_bpa_line_number');

debug('begin parameter validation: p_rel_line_number');
IF p_rel_line_number IS NOT NULL THEN
BEGIN
SELECT POLL.SHIPMENT_NUM
INTO l_exists_val
FROM PO_RELEASES_ALL POR, PO_LINE_LOCATIONS_ALL POLL, PO_HEADERS_ALL POH
WHERE POLL.SHIPMENT_NUM = p_rel_line_number
 AND poh.segment1 = p_doc_number
and por.release_num = p_doc_release
and por.po_header_id = poh.po_header_id
and por.po_release_id = poll.po_release_id
and p_doc_type = 'REL'
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: The Release Shipment Number is incorrect!');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_rel_line_number failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_rel_line_number');

debug('begin parameter validation: p_include_apps_check');
IF p_include_apps_check IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Include Diagnostic Apps Check is required.');
   raise invalid_parameters;
END IF;
IF p_include_apps_check IS NOT NULL AND p_include_apps_check NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Incorrect Include Diagnostic Apps Check Parameter.
Values should be either Y or N.');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_include_apps_check');


debug('begin parameter validation: p_debug_mode');
IF p_debug_mode IS NOT NULL AND p_debug_mode NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Debug Mode is invalid.  Valid values are Y or N');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_debug_mode');



-- Validation to verify analyzer is run on proper e-Business application version
-- In case validation at the beginning is updated/removed, adding validation here also so execution fails

  IF substr(l_apps_version,1,4) NOT IN ('12.0','12.1','12.2') THEN
    print_log('eBusiness Suite version = '||l_apps_version);
    print_log('ERROR: This Analyzer script is compatible for following version(s): 12.0,12.1,12.2');
    raise invalid_parameters;
  END IF;

-- .log enhancements (ER # 140)
  print_log(chr(10)||'Instance Information:');
  print_log('---------------------------');
  -- Do not report host details (EBSAF-274); reverted by EBSAF-293
  print_log('Host: '||g_rep_info('Host'));
  print_log('FullHost: '||g_rep_info('FullHost'));
  print_log('Instance: '||g_rep_info('Instance'));
  print_log('Database name: '||g_rep_info('DB Name'));
  print_log('Database version: '||g_rep_info('DB Version'));
  print_log('Applications version: '||g_rep_info('Apps Version'));
  print_log('Analyzer version: '||g_rep_info('File Version'));
  -- Report call details for troubleshooting (EBSAF-265)
  print_log('Calling method: '||g_rep_info('Calling From') );
  print_log('Calling module: '||g_rep_info('Calling Module') );
  print_log('---------------------------');

  -- Log session details (EBSAF-308)
  l_step := '8.5';
  print_log(chr(10)||'Session Information:');
  print_log('---------------------------');
  print_log('Language Code: '||sys_context('USERENV', 'LANG'));
  print_log('Region: '||sys_context('USERENV', 'NLS_TERRITORY'));
  print_log('Locale: '||sys_context('USERENV', 'LANGUAGE'));
  print_log('Date Format: '||sys_context('USERENV', 'NLS_DATE_FORMAT'));
  -- Get number characters
  select max(value) into l_system_function_var from v$parameter where name = 'nls_numeric_characters';
  print_log('Number Characters: '||l_system_function_var);
  -- Check for language installation
  begin
    execute immediate 'select max(installed_flag) from FND_LANGUAGES where language_code = sys_context(''USERENV'', ''LANG'')' into l_system_function_var;
    if (l_system_function_var is null or l_system_function_var not in ('B', 'I')) then
      print_log('WARNING: FND_LANGUAGES shows the session language is not installed.');
      print_log('Signatures relying on translation information may have incorrect results.');
    end if;
  exception when others then
    print_log('WARNING: Failed to check FND_LANGUAGES if session language is installed.');
  end;
  print_log('---------------------------');

  -- Verify escape character is set properly (EBSAF-265)
  l_step := '9';
  IF regexp_replace('Replace Test', '\s', '*') <>
     regexp_replace('Replace Test', chr(92) || 's', '*') THEN
    print_log('Invalid Escape:  Expected "' || chr(92) || 's' ||'" Received "\s"');
    print_log('Backslash character was not escaped properly during installation or execution.');
    raise invalid_escape;
  END IF;

  l_step := '10';
----------------------------------------------------------------
-- Analyzer-specific code: Additional Validation              --
----------------------------------------------------------------
debug('begin Additional Code: Additional Validation');
-- Accommodations for 19C DB
g_db_version    := l_dbversion;

select CASE 
WHEN g_db_version > '18'
THEN 'banner_full'
Else 'banner'
END into l_DBbanner from dual where rownum=1;

g_DBbanner := l_DBbanner;



BEGIN
  l_step := '01';
  l_trx_type := p_doc_type;

--Constants for use in -fails when- clause of sigs
g_c_shared := 'Shared';
g_c_no := 'No';

  l_step := '10';
  IF p_doc_number IS NOT NULL THEN
     g_trx_num := p_doc_number;
  END IF;  
  
  l_step := '20';
  IF p_doc_type IN ('PO', 'BPA', 'REL') THEN
     SELECT po_header_id INTO l_doc_id 
       FROM po_headers_all 
      WHERE org_id = p_org_id
       AND type_lookup_code <> 'QUOTATION' 
       AND type_lookup_code <> 'RFQ' 
        AND segment1 = to_char(p_doc_number)
        AND rownum = 1;
  ELSIF p_doc_type IN ('REQ', 'REQUISITION') THEN
     SELECT requisition_header_id INTO l_doc_id 
       FROM po_requisition_headers_all 
      WHERE org_id = p_org_id
        AND segment1 = to_char(p_doc_number)       
        AND rownum = 1;
  ELSIF p_doc_type IN ('RFQ','QUOTATION') THEN
     SELECT po_header_id INTO l_doc_id 
       FROM po_headers_all 
      WHERE org_id = p_org_id
       AND ( type_lookup_code = 'QUOTATION' 
       OR type_lookup_code = 'RFQ' )
        AND segment1 = to_char(p_doc_number)
        AND rownum = 1;
  END IF;
  

EXCEPTION WHEN NO_DATA_FOUND THEN
  print_log ('No data found in PO/REQ validation.');
  l_doc_id := NULL;
  raise INVALID_PARAMETERS;
END;

l_step := '30';
IF (p_doc_release is not null AND
    (p_doc_type <> 'REL' OR p_doc_number is null)) OR
   ((p_doc_release is null OR p_doc_number is null) AND
    p_doc_type = 'REL') THEN
  print_error('Invalid combination. For a release the transaction type '||
    'should be REL and the release number and PO number '||
    'must both be provided');
  print_log('Invalid combination. For a release the transaction type '||
    'should be REL and the release number and PO number '||
    'must both be provided');
  raise invalid_parameters;
END IF;

l_step := '40';
IF p_doc_release is not null THEN
  l_step := '50';
  BEGIN
    SELECT h.po_header_id, r.po_release_id,r.po_release_id porelid ,r.release_type,
           r.wf_item_type, r.wf_item_key, r.created_by, h.style_id
    INTO   l_doc_id, l_release_id, l_po_release_id, l_doc_subtype,
           l_item_type, l_item_key, l_created_by, l_style_id
    FROM   po_headers_all h, po_releases_all r
    WHERE  h.segment1 = p_doc_number
    AND    h.org_id = p_org_id
    AND    r.org_id = h.org_id
    AND    r.po_header_id = h.po_header_id
    AND    r.release_num = p_doc_release;
  EXCEPTION WHEN NO_DATA_FOUND THEN
    print_error('Invalid release, PO and org_id combination	');
    print_error('No release document exists for values '||
      to_char(p_doc_release)||'/'||p_doc_number||'/'||to_char(p_org_id));
    print_log('Invalid release, PO and org_id combination	');
    print_log('No release document exists for values '||
      to_char(p_doc_release)||'/'||p_doc_number||'/'||to_char(p_org_id));
    raise invalid_parameters;
  END;

END IF;

l_step := '60';

  BEGIN
    IF (p_doc_type = 'PO' AND p_po_line_number is not null) THEN
        l_step := '62';
        select pol.po_line_id into l_line_id
          from apps.po_lines_all pol
         where po_header_id = l_doc_id
           and pol.line_num = p_po_line_number ;
    ELSIF (p_doc_type = 'REQ' AND p_req_line_number is not null) THEN
        l_step := '64';
        select prl.requisition_line_id into l_line_id
          from apps.po_requisition_lines_all prl
         where requisition_header_id = l_doc_id
           and prl.line_num = p_req_line_number ;
    ELSIF (p_doc_type = 'BPA' AND p_bpa_line_number is not null) THEN
        l_step := '64';
        select pol.po_line_id into l_line_id
          from apps.po_lines_all pol
         where po_header_id = l_doc_id
           and pol.line_num = p_bpa_line_number ;
    ELSIF (p_doc_type = 'REL' AND p_rel_line_number is not null) THEN
        l_step := '66';
        select poll.line_location_id into l_line_id 
          from po_releases_all por, po_line_locations_all poll, po_lines_all pol
         where por.po_header_id = l_doc_id
           and por.po_release_id = l_release_id
           and substr(poll.shipment_num,0,5) = p_rel_line_number 
           and por.po_release_id = poll.po_release_id
           and pol.po_line_id = poll.po_line_id;
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
       l_line_id := NULL;
       print_log('Entered document line number not found for document type ' || p_doc_type || ' and document id ' || l_doc_id ||'.');
       raise invalid_parameters;
    WHEN OTHERS THEN
       l_line_id := NULL;
       print_log('Exception when trying to retrieve line id for document: ' ||SQLERRM);
       raise invalid_parameters;
   END;    

l_step := '70';
  if p_doc_type = 'PO' then
    begin
                l_step := '72';
		select decode(count(*),0,'N','Y')
		into l_backing_req from dual
		where exists
		(select 1
		from po_distributions_all
		where po_header_id = l_doc_id
		and org_id         = p_org_id
		and req_distribution_id is not null);
    exception
      when others then
        print_log('Invalid backing requisition status.'||sqlerrm);
        raise invalid_parameters;
    end;

  elsif p_doc_type = 'REL' then
    begin
                l_step := '74';
		select decode(count(*),0,'N','Y')
		into l_backing_req from dual
		where exists
		(select 1
		from po_distributions_all d, po_releases_all r
		where d.po_header_id = r.po_header_id
		and d.org_id = r.org_id
		and d.po_release_id = r.po_release_id
		and d.po_header_id = l_doc_id
		and d.po_release_id = l_release_id
		and d.org_id         = p_org_id
		and d.req_distribution_id is not null);
    exception
      when others then
        print_log('Invalid backing requisition status.'||sqlerrm);
        raise invalid_parameters;
    end;
  end if;  

 
l_step := '90';
  if (p_doc_type = 'REQ' and l_doc_id is not null) then
    begin
		select decode(count(line_location_id),0,'N','Y')
		into l_assoc_po
		from po_requisition_lines_all
		where requisition_header_id = l_doc_id
		and org_id         = p_org_id;
    exception
      when others then
        print_log('Invalid associated PO status found for the requisition. '||sqlerrm);
        raise invalid_parameters;
    end;
  end if;

l_step := '100';
  -- populate set of books local variable (to be used in the SOBID token)
if (p_doc_type = 'PO' and l_doc_id is not null) then
  begin
     select oo.set_of_books_id 
      into l_sob_id
      from  financials_system_params_all fsp, 
          org_organization_definitions oo,
          po_headers_all poh
      where poh.org_id = fsp.org_id
        and fsp.inventory_organization_id = oo.organization_id
        and poh.po_header_id = l_doc_id;

      debug('Set of books id: ' || l_sob_id);
   exception when others then
      print_log('Could not determine set of books id! ' || SQLERRM);
   end; 
elsif p_doc_type = 'REL' and l_doc_id is not null then
    begin
      select oo.set_of_books_id 
      into l_sob_id
      from  financials_system_params_all fsp, 
          org_organization_definitions oo,
          po_releases_all rel
      where rel.org_id = fsp.org_id
        and fsp.inventory_organization_id = oo.organization_id
        and rel.po_release_id = l_release_id;

      debug('Set of books id: ' || l_sob_id);
   exception when others then
      print_log('Could not determine set of books id! ' || SQLERRM);
   end; 
  elsif p_doc_type = 'REQ' and l_doc_id is not null then
    begin
     select oo.set_of_books_id 
      into l_sob_id
      from  financials_system_params_all fsp, 
          org_organization_definitions oo,
          po_requisition_headers_all req
      where req.org_id = fsp.org_id
        and fsp.inventory_organization_id = oo.organization_id
        and req.requisition_header_id = l_doc_id;

      debug('Set of books id: ' || l_sob_id);
   exception when others then
      print_log('Could not determine set of books id! ' || SQLERRM);
   end; 
  end if;

l_step := '110';
   -- populate DEXP token
if (p_doc_type = 'PO' and l_doc_id is not null) then
   begin
      select decode(count(*),0,'N','Y')
        into l_dest_expense from dual
       where exists
          (select 1
             from po_distributions_all
            where po_header_id = l_doc_id
              and org_id         = p_org_id
              and DESTINATION_TYPE_CODE = 'EXPENSE');
   exception when others then
      print_log('Could not determine dest expense! ' || SQLERRM);
   end;
  
l_step := '115';
   -- populate DINV token
   begin
      select decode(count(*),0,'N','Y')
        into l_dest_inventory from dual
       where exists
          (select 1
             from po_distributions_all
            where po_header_id = l_doc_id
              and org_id         = p_org_id
              and DESTINATION_TYPE_CODE = 'INVENTORY');
   exception when others then
      print_log('Could not determine PO dest inventory! ' || SQLERRM);
   end;
 end if;

if (p_doc_type = 'REL' and l_doc_id is not null) then
l_step := '118';
   -- populate DINVREL token
   begin
      select decode(count(*),0,'N','Y')
        into l_dest_inventory_rel from dual
       where exists
          (select 1
             from po_distributions_all
            where po_header_id = l_doc_id
              and po_release_id = l_release_id 
              and org_id         = p_org_id
              and DESTINATION_TYPE_CODE = 'INVENTORY');
   exception when others then
      print_log('Could not determine REL dest inventory! ' || SQLERRM);
   end;
 end if;  

if (p_doc_type = 'REQ' and l_doc_id is not null) then
l_step := '120';
 -- populate INTREQ token
   begin
      select decode(count(*),0,'N','Y')
        into l_int_req from dual
       where exists
          (select 1
             from po_requisition_lines_all
            where requisition_header_id = l_doc_id
              and org_id         = p_org_id
              and source_type_code = 'INVENTORY');
   exception when others then
      print_log('Could not determine int_req! ' || SQLERRM);
   end;
 end if;

l_step := '130';
 -- check if Complex PO
   IF p_doc_type = 'PO' THEN
     begin
       select 'Y' into g_complex_po
       from po_doc_style_headers pdsh, po_headers_all pha 
       where (pdsh.advances_flag = 'Y' or pdsh.retainage_flag = 'Y' or pdsh.progress_payment_flag = 'Y') 
       and pdsh.style_id = pha.style_id and pha.po_header_id = l_doc_id;
     exception when NO_DATA_FOUND then
       print_log('Not a complex PO');
     end;
   END IF;

l_step := '140';
IF p_doc_type = 'PO' and l_doc_id is not null THEN
  -- populate legal entity id variable for PO
  begin
     -- For PO --
     select ho.default_legal_context_id 
      into l_legal_entity_id
      from  hr_operating_units ho, po_headers_all poh
      where poh.org_id = ho.organization_id
        and poh.po_header_id = l_doc_id;

      debug('Legal Entity Id: ' || l_legal_entity_id);
   exception when others then
      print_log('Could not determine legal entity id for PO! ' || SQLERRM);
   end; 
elsif p_doc_type = 'REQ' and l_doc_id is not null then
  -- populate legal entity id variable for REQ
  begin
     -- For REQ --
     select ho.default_legal_context_id 
      into l_legal_entity_id
      from  hr_operating_units ho, po_requisition_headers_all req
      where req.org_id = ho.organization_id
        and req.requisition_header_id = l_doc_id;

      debug('Legal Entity Id: ' || l_legal_entity_id);
   exception when others then
      print_log('Could not determine legal entity id for REQ! ' || SQLERRM);
   end; 

elsif p_doc_type = 'REL' and l_doc_id is not null then
  -- populate legal entity id variable for REL
  begin
     -- For REL --
     select ho.default_legal_context_id 
      into l_legal_entity_id
      from  hr_operating_units ho, po_releases_all rel
      where rel.org_id = ho.organization_id
        and rel.po_release_id = l_release_id;

      debug('Legal Entity Id: ' || l_legal_entity_id);
   exception when others then
      print_log('Could not determine legal entity id for REL! ' || SQLERRM);
   end; 
END IF;

IF p_doc_type = 'PO' and l_line_id is not null THEN

  l_step := '150';
 -- populate DROPSHIP token
   begin
      select decode(count(*),0,'N','Y')
        into l_drop_ship 
        from oe_drop_ship_sources oe, po_lines_all pol
        where oe.po_line_id = pol.po_line_id
        and pol.po_line_id like NVL(to_char(l_line_id),'%')
        and pol.po_header_id = l_doc_id;
      debug('Drop Ship: ' || l_drop_ship || ' l_doc_id ' || l_doc_id || ' l_line_id ' || l_line_id || ' p_doc_type ' || p_doc_type );
   exception when others then
      print_log('Could not determine if drop ship or not! ' || SQLERRM);
   end;

END IF;

IF p_doc_type = 'PO' and l_line_id is null THEN

  l_step := '155';
 -- populate DROPSHIP token
   begin
      select decode(count(*),0,'N','Y')
        into l_drop_ship 
        from oe_drop_ship_sources oe, po_lines_all pol
        where oe.po_line_id = pol.po_line_id
        and pol.po_header_id = l_doc_id;
      debug('Drop Ship: ' || l_drop_ship || ' l_doc_id ' || l_doc_id || ' l_line_id ' || l_line_id || ' p_doc_type ' || p_doc_type );
   exception when others then
      print_log('Could not determine if drop ship or not! ' || SQLERRM);
   end;

END IF;

l_step := '160';

--Framework
g_instance := l_instance;
g_apps_version := l_apps_version;

l_step := '170';
-- Obtain FWK level
select codelevel into l_fwk_level
from AD_TRACKABLE_ENTITIES where abbreviation = ('fwk');

l_step := '180';

-- Set Global Variables for Messaging
g_fwk_level := l_fwk_level;

l_step := '190';

-- check if column exists in table 
g_HasClmTotQtyOrd := 'N';
begin
  select decode(count(*),0,'N','Y') into g_HasClmTotQtyOrd
  from dba_tab_cols where column_name = 'CLM_TOTAL_QUANTITY_ORDERED' and table_name = 'PO_LINES_ALL';
   exception when others then
      print_log('Could not find column CLM_TOTAL_QUANTITY_ORDERED in PO_LINES_ALL! ' || SQLERRM);
end;


    /* SEEDED EBS BANNER BEGIN */

    -- Premier Support Checks by priority
    select min(error_type) into l_system_function_var from (
        -- Database in Sustaining Support
        select 1 error_type from V$VERSION WHERE banner like '%11.2%' or banner like '%11.1%' or banner like '%10.%'
        union
        -- Application Version 11.5
        select 2 error_type from fnd_product_groups where release_name like '11.5%'
        union
        -- Application Version 12.1
        select 3 error_type from fnd_product_groups where release_name like '12.1%'
        union
        -- Database in Extended Support
        select 4 error_type from V$VERSION WHERE banner like '%12.1%'
        union
        -- Application Version 12.0
        select 5 error_type from fnd_product_groups where release_name like '12.0%'
        union
        -- Application Version 12.2.x outdated
        select 6 error_type from fnd_product_groups where release_name in ('12.2.0' , '12.2.1' , '12.2.2' , '12.2.3' , '12.2.4' , '12.2.5' , '12.2.6')
    );

    -- Set banner message by error type
    case l_system_function_var
        when 1 then
            -- Database in Sustaining Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Sustaining Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 2 then
            -- Application Version 11.5
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on November 2010. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br> Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 3 then
            -- Application Version 12.1
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support End for the application version on this instance is on December 2021. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp]. <br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 4 then
            -- Database in Extended Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Extended Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 5 then
            -- Application Version 12.0
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on January 2012. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 6 then
           -- Application Version 12.2.7
           g_banner_severity := 'W';
           g_banner_message := '<b>Effective July 1, 2024, the E-Business Suite 12.2 Error Correction Baseline will be 12.2.7.</b><br>
<br>
<div><div style="display:inline-block; text-align:left; max-width:800px;">Updating the application version to release 12.2.7 or higher will ensure you have access to major product releases.<br>
Refer to:<ul>
<li>[1195034/KB696368] Oracle E-Business Suite Error Correction Support Policy</li>
<li><a href="https://blogs.oracle.com/ebstech/post/update-error-correction-baseline-for-ebs-122" target="_blank">Oracle E-Business Suite Technology Blog</a> Update: Error Correction Baseline for EBS 12.2</li>
</ul>
Customers running E-Business Suite products on the 12.2.3 - 12.2.6 release levels are encouraged to update to current code levels of those products before July 2024 so they can benefit from the simpler and smaller patches that will be available starting in July 2024.<br>
In the event a new issue is reported on a product at a code level below the baseline, Oracle Support will attempt to resolve the issue and engage Development if necessary. Development may determine that the issue can be resolved at the customer code level, or may determine that the only practical way to provide the fix is for the customer to apply the baseline (or later) code in the affected area, and provide the fix at that level.
</div></div>';
        else
            -- No banner required
            g_banner_message := null;
    end case;
    /* SEEDED EBS BANNER END */
debug('end Additional Code: Additional Validation');



  g_parameters.DELETE;

  -- Recreate global hash for parameters after validation (includes the modifiers)
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Unit';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Document Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_doc_type,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Document Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_doc_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Release Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_doc_release,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Requisition Line Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_req_line_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'PO Line Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_po_line_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'BPA Line Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_bpa_line_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Release Shipment Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_rel_line_number,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Diagnostic Apps Check';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_include_apps_check,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  l_step := '11';
  print_log(chr(10)||'Parameter Values after validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  -- Create global hash of SQL token values
debug('begin populate sql tokens hash table');
   g_sql_tokens('##$$DOCNUM$$##') := p_doc_number;
   g_masked_tokens('##$$DOCNUM$$##') := mask_text( g_sql_tokens('##$$DOCNUM$$##'), 'NO_MASK');
   g_sql_tokens('##$$DOCID$$##') := l_doc_id;
   g_masked_tokens('##$$DOCID$$##') := mask_text( g_sql_tokens('##$$DOCID$$##'), 'NO_MASK');
   g_sql_tokens('##$$ORGID$$##') := p_org_id;
   g_masked_tokens('##$$ORGID$$##') := mask_text( g_sql_tokens('##$$ORGID$$##'), 'NO_MASK');
   g_sql_tokens('##$$DOCTYPE$$##') := p_doc_type;
   g_masked_tokens('##$$DOCTYPE$$##') := mask_text( g_sql_tokens('##$$DOCTYPE$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM1$$##') := '201';
   g_masked_tokens('##$$APPS_PARAM1$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM1$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM2$$##') := '178';
   g_masked_tokens('##$$APPS_PARAM2$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM2$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM3$$##') := 'null';
   g_masked_tokens('##$$APPS_PARAM3$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM3$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM4$$##') := 'null';
   g_masked_tokens('##$$APPS_PARAM4$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM4$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_PARAM5$$##') := 'null';
   g_masked_tokens('##$$APPS_PARAM5$$##') := mask_text( g_sql_tokens('##$$APPS_PARAM5$$##'), 'NO_MASK');
   g_sql_tokens('##$$RELID$$##') := nvl(to_char(l_release_id),'NULL');
   g_masked_tokens('##$$RELID$$##') := mask_text( g_sql_tokens('##$$RELID$$##'), 'NO_MASK');
   g_sql_tokens('##$$IS_BREQ$$##') := l_backing_req;
   g_masked_tokens('##$$IS_BREQ$$##') := mask_text( g_sql_tokens('##$$IS_BREQ$$##'), 'NO_MASK');
   g_sql_tokens('##$$IS_AUCRPO$$##') := l_assoc_po;
   g_masked_tokens('##$$IS_AUCRPO$$##') := mask_text( g_sql_tokens('##$$IS_AUCRPO$$##'), 'NO_MASK');
   g_sql_tokens('##$$LINEID$$##') := l_line_id;
   g_masked_tokens('##$$LINEID$$##') := mask_text( g_sql_tokens('##$$LINEID$$##'), 'NO_MASK');
   g_sql_tokens('##$$SOBID$$##') := nvl(to_char(l_sob_id),-1);
   g_masked_tokens('##$$SOBID$$##') := mask_text( g_sql_tokens('##$$SOBID$$##'), 'NO_MASK');
   g_sql_tokens('##$$DEXP$$##') := nvl(to_char(l_dest_expense),'Y');
   g_masked_tokens('##$$DEXP$$##') := mask_text( g_sql_tokens('##$$DEXP$$##'), 'NO_MASK');
   g_sql_tokens('##$$REL$$##') := g_rep_info('Apps Version');
   g_masked_tokens('##$$REL$$##') := mask_text( g_sql_tokens('##$$REL$$##'), 'NO_MASK');
   g_sql_tokens('##$$INTREQ$$##') := l_int_req;
   g_masked_tokens('##$$INTREQ$$##') := mask_text( g_sql_tokens('##$$INTREQ$$##'), 'NO_MASK');
   g_sql_tokens('##$$APPS_CHECK$$##') := p_include_apps_check;
   g_masked_tokens('##$$APPS_CHECK$$##') := mask_text( g_sql_tokens('##$$APPS_CHECK$$##'), 'NO_MASK');
   g_sql_tokens('##$$DINV$$##') := nvl(to_char(l_dest_inventory),'Y');
   g_masked_tokens('##$$DINV$$##') := mask_text( g_sql_tokens('##$$DINV$$##'), 'NO_MASK');
   g_sql_tokens('##$$DINVREL$$##') := nvl(to_char(l_dest_inventory_rel),'Y');
   g_masked_tokens('##$$DINVREL$$##') := mask_text( g_sql_tokens('##$$DINVREL$$##'), 'NO_MASK');
   g_sql_tokens('##$$LEGAL_ENTITY_ID$$##') := nvl(to_char(l_legal_entity_id),-1);
   g_masked_tokens('##$$LEGAL_ENTITY_ID$$##') := mask_text( g_sql_tokens('##$$LEGAL_ENTITY_ID$$##'), 'NO_MASK');
   g_sql_tokens('##$$DROPSHIP$$##') := l_drop_ship;
   g_masked_tokens('##$$DROPSHIP$$##') := mask_text( g_sql_tokens('##$$DROPSHIP$$##'), 'NO_MASK');
   g_sql_tokens('##$$ORG_ID$$##') := p_org_id;
   g_masked_tokens('##$$ORG_ID$$##') := mask_text( g_sql_tokens('##$$ORG_ID$$##'), 'NO_MASK');
   g_sql_tokens('##$$HEADID$$##') := l_doc_id;
   g_masked_tokens('##$$HEADID$$##') := mask_text( g_sql_tokens('##$$HEADID$$##'), 'NO_MASK');
   g_sql_tokens('##$$DOCTYPESHORT$$##') := get_DOCTYPESHORT();
   l_system_function_var := null;
   g_masked_tokens('##$$DOCTYPESHORT$$##') := mask_text( g_sql_tokens('##$$DOCTYPESHORT$$##'), 'NO_MASK');
   g_sql_tokens('##$$PORELID$$##') := l_po_release_id;
   g_masked_tokens('##$$PORELID$$##') := mask_text( g_sql_tokens('##$$PORELID$$##'), 'NO_MASK');
   g_sql_tokens('##$$HEADERID$$##') := l_doc_id;
   g_masked_tokens('##$$HEADERID$$##') := mask_text( g_sql_tokens('##$$HEADERID$$##'), 'NO_MASK');
   g_sql_tokens('##$$LVIEW$$##') := 'SELECT /*+ qb_name(lview) */ '||
     'DISTINCT l.invoice_id,l.line_number '||
     'FROM ap_invoice_lines_all l '||
     'WHERE l.org_id in ('||g_org_ids||') '||
     'AND   l.accounting_date BETWEEN '||
     '        to_date('''||g_start_date||''') AND '||
     '        to_date('''||g_end_date||''')';
   g_masked_tokens('##$$LVIEW$$##') := mask_text( g_sql_tokens('##$$LVIEW$$##'), 'NO_MASK');
   g_sql_tokens('##$$FWK$$##') := l_fwk_level;
   g_masked_tokens('##$$FWK$$##') := mask_text( g_sql_tokens('##$$FWK$$##'), 'NO_MASK');
debug('end populate sql tokens hash table');



  l_key := g_masked_tokens.first;
  -- Print token values to the log

  -- if max rows param is not set and does not have a default, g_max_output_rows might end up being -1. We don't want that.
  IF (g_max_output_rows <= 0) THEN
     print_log ('Max rows was not set and there is no default value for it. Defaulting to 20.');
     g_max_output_rows := 20;
  ELSIF (g_max_output_rows > 100000) THEN
     print_log ('Max rows was set too high. Defaulting to 100000.');
     g_max_output_rows := 100000;
  END IF;

  l_step := '12';
  print_log('SQL Token Values');

  WHILE l_key IS NOT NULL LOOP
    -- Ensure tokens do not contain invalid characters (EBSAF-263)
    g_sql_tokens(l_key) := filter_html(g_sql_tokens(l_key), 'I', 'D' );
    g_masked_tokens(l_key) := filter_html(g_masked_tokens(l_key), 'I', 'D' );

    -- Allow tokens to be masked in log (EBSAF-275)
    print_log(l_key||': '|| g_masked_tokens(l_key));
    l_key := g_masked_tokens.next(l_key);
  END LOOP;

EXCEPTION
  WHEN INVALID_PARAMETERS THEN
    print_error_args('Invalid parameters provided. Process cannot continue.', l_step);
    raise;
  WHEN INVALID_ESCAPE THEN
    print_error('INVALID ESCAPE: Regular expression search results are incorrect.' ||
        ' Calling method "' || g_rep_info('Calling From') || '" module "' || g_rep_info('Calling Module') || '".' );
    raise;
  WHEN OTHERS THEN
    print_error_args('Error validating parameters: '||sqlerrm, l_step);
    raise;
END validate_parameters;


