debug('begin add_signature: POA_AME_ENABLED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8518',
      p_sig_id                 => 'POA_AME_ENABLED',
      p_sig_sql                => 'SELECT dt.type_name,
           dt.document_type_code,
           dt.document_subtype,
           dt.ame_transaction_type,
           dt.wf_approval_itemtype,
           dt.wf_approval_process
FROM po_document_types_all dt
WHERE dt.org_id = ##$$ORGID$$##
AND dt.ame_transaction_type IS NOT NULL',
      p_title                  => 'Approvals Management Engine (AME) Enabled',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The Approvals Management Engine (AME) is enabled for the listed document types in ORG_ID ##$$ORGID$$##.',
      p_solution               => '<ul>
<li>If you have intentionally enabled AME, please be aware that PO AME Approval supports only Requisitions, Standard Purchase Orders and Global Purchase Agreements.</li>
<li>If not, you should disable AME for these document types:
    <ol>
        <li>Query up the document type in the Purchasing > Document Types form.</li>
        <li>Delete the value in the "Approval Transaction Type" field. This will be PURCHASE_REQ for Purchase Requisitions,INTERNAL_REQ for Internal Requisitions and RCO for Change Order Request: Requisitions, PURCHASE_ORDER for Purchase Orders.</li>
        <li>See [470204/KB360769] for details and screen shots.</li></ol>
</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
