debug('begin add_signature: GL_PERIOD_NOT_OPEN');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('##STYLE##GL_PERIOD_STATUS'):= 'left,#333333,#FFE864,bold';
  add_signature(
      p_sig_repo_id            => '8550',
      p_sig_id                 => 'GL_PERIOD_NOT_OPEN',
      p_sig_sql                => 'SELECT GPS.SET_OF_BOOKS_ID, ood.ORGANIZATION_ID, GPS.PERIOD_NAME,
DECODE(GPS.CLOSING_STATUS,''O'',''Open'', ''C'',''Closed'', ''F'',''Future'', ''N'',''Never Opened'', CLOSING_STATUS) "GL_PERIOD_STATUS",
GPS.START_DATE, GPS.END_DATE
FROM GL_PERIOD_STATUSES GPS, org_organization_definitions OOD
WHERE GPS.CLOSING_STATUS <> ''O''
AND TRUNC(GPS.START_DATE,''YEAR'') = TRUNC(sysdate,''YEAR'')
AND TRUNC(GPS.START_DATE,''MONTH'') = TRUNC(sysdate,''MONTH'')
AND GPS.APPLICATION_ID = 101
AND GPS.SET_OF_BOOKS_ID = OOD.SET_OF_BOOKS_ID and ood.ORGANIZATION_ID = ##$$ORGID$$##
ORDER BY GPS.APPLICATION_ID, GPS.START_DATE DESC',
      p_title                  => 'General Ledger Period for the Current Date is Not Open',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The General Ledger (GL) Period for the current date is not "Open" for the Set of Books associated to this Operating Unit.',
      p_solution               => 'Open the General Ledger Period to allow users to create receipts for the current date.  
Reference: [175392/KB646627] How To Open Periods So Receiving Can Be Completed?
',
      p_success_msg            => 'The General Ledger Period is "Open" for the current date.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: GL_PERIOD_NOT_OPEN');



