debug('begin add_signature: NO_VALID_EMPLOYEE_BUYER_REQ_POOL_SPECIFIC');
   l_info('##MASK##DESCRIPTION'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8524',
      p_sig_id                 => 'NO_VALID_EMPLOYEE_BUYER_REQ_POOL_SPECIFIC',
      p_sig_sql                => 'select  r.segment1 Requisition_Number, RL.LINE_NUM Req_Line_Number ,suggested_buyer_id BUYER_ID,r.creation_date Req_Creation_Date, r.description ,rl.Need_By_Date,r.Preparer_ID 
       from po_requisition_lines rl,
            po_requisition_headers r
WHERE 1=1
and rl.suggested_buyer_id is not null
and rl.requisition_header_id = ##$$DOCID$$##
AND R.AUTHORIZATION_STATUS = ''APPROVED''
and suggested_buyer_id is not null
and nvl(rl.closed_code,''OPEN'')  <> ''FINALLY CLOSED''
AND  nvl(RL.reqs_in_pool_flag, ''N'') =  ''Y''
and SUGGESTED_BUYER_ID  not in --not valid emp if not in view
(
select person_id
from per_workforce_current_x ppf    --not a current employee
)
order by 1,2 asc',
      p_title                  => 'Employee Record Not Active For the Suggested Buyer',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The suggested buyer listed on requisition '||mask_text(g_trx_num, nvl( upper(''), 'NO_MASK') )||' lines is no longer an active employee.',
      p_solution               => 'See [2071019/KB308908] - How to Check Purchasing Buyer Data and Corresponding Employee Data for the Buyer.',
      p_success_msg            => 'All buyers have valid employee records.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: NO_VALID_EMPLOYEE_BUYER_REQ_POOL_SPECIFIC');



debug('begin add_signature: TERMINATE_BUYER_IN_REQ_POOL_APPROVED_SPECIFIC');
   l_info('##MASK##BUYER_NAME'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##DESCRIPTION'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##FULL_NAME'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8527',
      p_sig_id                 => 'TERMINATE_BUYER_IN_REQ_POOL_APPROVED_SPECIFIC',
      p_sig_sql                => 'select r.segment1 Requisition_Number,  
       RL.LINE_NUM Req_Line_Number ,
       suggested_buyer_id BUYER_ID,
       nvl(hr.full_name,''NO NAME'') BUYER_NAME,
       r.creation_date Req_Creation_Date, 
       r.description ,
       rl.Need_By_Date,
       r.Preparer_ID
       from po_requisition_lines rl,
            po_requisition_headers r,  per_workforce_current_x hr
WHERE
   1=1
   and rl.requisition_header_id = ##$$DOCID$$##
   AND R.AUTHORIZATION_STATUS = ''APPROVED''
   and nvl(rl.closed_code,''OPEN'')  <> ''FINALLY CLOSED''
   AND  nvl(RL.reqs_in_pool_flag, ''N'') =  ''Y''
   and suggested_buyer_id is not null
  -- and pag.agent_id = suggested_buyer_id
   and hr.person_id (+) = suggested_buyer_id --outer join in case inactive
   and suggested_buyer_id in   (
      SELECT  agent_id FROM PO_AGENTS
      where end_date_active is not null
        )
    order by 1, 2 asc',
      p_title                  => 'Buyer On Requisition Is Not An Active Buyer',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Terminated buyer in the approved requisition pool for requisition '||mask_text(g_trx_num, nvl( upper(''), 'NO_MASK') )||'.',
      p_solution               => 'See [2071019/KB308908] - How to Check Purchasing Buyer Data and Corresponding Employee Data for the Buyer.',
      p_success_msg            => 'There are no terminated buyers in the approved requisition pool.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: TERMINATE_BUYER_IN_REQ_POOL_APPROVED_SPECIFIC');



