debug('begin add_signature: PRC_PO_MISSING_BASE_TABLES');
   l_info('##MASK##%ATTRIBUTE%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##%NOTE%'):= 'DISPLAY_NONE';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11556',
      p_sig_id                 => 'PRC_PO_MISSING_BASE_TABLES',
      p_sig_sql                => 'SELECT *
FROM po_headers_archive_all
WHERE po_header_id = ##$$DOCID$$##
and po_header_id NOT IN
((SELECT po_header_id FROM po_headers_all)
UNION
(SELECT PDAA.po_header_id
FROM po_distributions_archive_all PDAA,
PO_DISTRIBUTIONS_ALL PDA,
PO_REQUISITION_LINES_ALL PRL,
PO_REQ_DISTRIBUTIONS_ALL PRD
WHERE PDAA.po_distribution_id NOT IN
(SELECT po_distribution_id FROM po_distributions_all)
AND PDAA.REQ_DISTRIBUTION_ID IS NOT NULL
AND PDAA.REQ_DISTRIBUTION_ID = PDA.REQ_DISTRIBUTION_ID
AND PDAA.REQ_DISTRIBUTION_ID = PRD.DISTRIBUTION_ID
AND PRL.requisition_line_id = PRD.requisition_line_id
AND PDAA.line_location_id != PRL.line_location_id
AND NVL(PRL.REQS_IN_POOL_FLAG, ''N'') = ''N''
AND PDAA.latest_external_flag =''Y''
))',
      p_title                  => 'Missing Records in PO Base Tables But Exist in Archive Tables',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are records in the archive tables, but the same records are missing in the PO base tables (ie. POL, PLL and POD).',
      p_solution               => 'See [1547080/KB717054] for solution.',
      p_success_msg            => 'No data corruption found.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: PRC_PO_MISSING_BASE_TABLES');



