debug('begin add_signature: PRC_PO_WRONG_ACCRUE_ON_RECEIPT_FLAG_N_Y');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('##STYLE##ACTION_PLAN'):= 'left,#333333,#ffd6cc,bold';
   l_info('##STYLE##ACTUAL_ACRF_ON_DIST'):= 'left,#333333,#ffd6cc,bold';
   l_info('##STYLE##ACTUAL_ACRF_ON_SHP'):= 'left,#333333,#ffd6cc,bold';
  add_signature(
      p_sig_repo_id            => '11551',
      p_sig_id                 => 'PRC_PO_WRONG_ACCRUE_ON_RECEIPT_FLAG_N_Y',
      p_sig_sql                => 'SELECT
h.segment1 PO#,
l.line_num Line#,
s.shipment_num Shipment#,
d.distribution_num Distribution#,
d.destination_type_code Destination_type_code,
psp.expense_accrual_code Exp_Accrual_code_Setup,
s.receipt_required_flag Rcpt_req_flag_on_shipment,
''N (Correct)'' Expctd_ACRF_on_DIST,
''Y (Wrong)'' Actual_ACRF_on_DIST,
''N (Correct)'' Expctd_ACRF_on_SHP,
Decode ( Nvl(s.accrue_on_receipt_flag, ''N''),
''N'', ''N (Correct)'',
''Y'', ''Y (Wrong)''
) Actual_ACRF_on_SHP,
Decode (l.matching_basis,
''QUANTITY'', Nvl(d.quantity_ordered, 0),
''AMOUNT'', Nvl(d.amount_ordered, 0)
) ordered_on_Distribution,
Decode (l.matching_basis,
''QUANTITY'', Nvl(d.quantity_delivered, 0),
''AMOUNT'', Nvl(d.amount_delivered, 0)
) Delivered_on_Distribution,
Decode (l.matching_basis,
''QUANTITY'', Nvl(d.quantity_billed, 0),
''AMOUNT'', Nvl(d.amount_billed, 0)
) Billed_on_Distribution,
h.po_header_id po_header_id,
l.po_line_id po_line_id,
s.line_location_id line_location_id,
d.po_distribution_id po_distribution_id,
l.matching_basis Matching_Basis,
h.authorization_status APPROVAL_STATUS,
Decode (l.matching_basis,
''QUANTITY'', Decode( Nvl(d.quantity_billed, 0), 0,'''', ''Cancel Invoice now and recreate invoice after data fix. '') ,
''AMOUNT'', Decode( Nvl(d.amount_billed, 0), 0,'''', ''Cancel Invoice now and recreate invoice after data fix. '')
) ||
Decode (l.matching_basis,
''QUANTITY'', Decode( Nvl(d.quantity_delivered, 0), 0,'''', ''Return Receipt now and recreate Receipt after datafix. ''),
''AMOUNT'', Decode( Nvl(d.amount_delivered, 0), 0,'''', ''Return Receipt now and recreate Receipt after data fix. '')
) Action_Plan
FROM
po_headers_all h,
po_lines_all l,
po_line_locations_all s,
po_distributions_All d,
po_system_parameters_All psp
WHERE
/*joins start */
h.po_header_id = l.po_header_id
AND l.po_line_id = s.po_line_id
AND s.line_location_id = d.line_location_id
AND psp.org_id = h.org_id
AND NVL( s.CANCEL_FLAG, ''N'' ) <> ''Y''
AND NVL( s.CLOSED_CODE, ''OPEN'' ) <> ''FINALLY CLOSED''
/* joins end */
/*
For Expense destination, ACRF depends on set up which i have fetched from
po_system_parameters_All.
If expense accrual code is ''PERIOD END'', then expense destination should have ACRF as N
So the below conditions ensure that we get data whose ACRF is supposed to be N but actually is Y
*/
AND d.destination_type_code = ''EXPENSE''
AND ( (psp.EXPENSE_ACCRUAL_CODE = ''PERIOD END''AND (d.accrue_on_receipt_flag = ''Y'' or s.accrue_on_receipt_flag = ''Y''))
or
(psp.EXPENSE_ACCRUAL_CODE = ''RECEIPT'' and Nvl(s.receipt_required_flag, ''N'') = ''N'' and ( Nvl(s.accrue_on_receipt_flag, ''N'') = ''Y'' or Nvl(d.accrue_on_receipt_flag, ''N'') = ''Y'' ))
)
/*the logic explained in above comments is true only if the following are true */
AND Nvl(s.CONSIGNED_FLAG, ''N'') = ''N''
AND s.shipment_type <> ''PREPAYMENT''
AND d.award_id IS NULL
AND h.PCARD_ID IS NULL
AND h.po_header_id = ##$$DOCID$$##',
      p_title                  => 'Incorrect ACCRUE_ON_RECEIPT_FLAG - Correct N Actual Y',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The Accrue at Receipt flag is not correct and requires a datafix: Correct NO Actual YES.',
      p_solution               => 'See [1629692/KB197343] for solution.',
      p_success_msg            => 'No data corruption found.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: PRC_PO_WRONG_ACCRUE_ON_RECEIPT_FLAG_N_Y');



debug('begin add_signature: PRC_PO_WRONG_ACCRUE_ON_RECEIPT_FLAG_Y_N');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('##STYLE##ACTION_PLAN'):= 'left,#333333,#ffd6cc,bold';
   l_info('##STYLE##ACTUAL_ACRF_ON_DIST'):= 'left,#333333,#ffd6cc,bold';
   l_info('##STYLE##ACTUAL_ACRF_ON_SHP'):= 'left,#333333,#ffd6cc,bold';
  add_signature(
      p_sig_repo_id            => '11550',
      p_sig_id                 => 'PRC_PO_WRONG_ACCRUE_ON_RECEIPT_FLAG_Y_N',
      p_sig_sql                => 'SELECT 
   h.segment1 PO#,
   l.line_num Line#,
   s.shipment_num Shipment#,
   d.distribution_num Distribution#,
   d.destination_type_code Destination_type_code,
   psp.expense_accrual_code Exp_Accrual_code_Setup,
   s.receipt_required_flag Rcpt_req_flag_on_shipment,
  ''Y (Correct)'' Expctd_ACRF_on_DIST,
  ''N (Wrong)''   Actual_ACRF_on_DIST,
  ''Y (Correct)'' Expctd_ACRF_on_SHP,
  Decode ( Nvl(s.accrue_on_receipt_flag, ''N''),
           ''Y'', ''Y (Correct)'',
           ''N'', ''N (Wrong)''
         ) Actual_ACRF_on_SHP,
  Decode (l.matching_basis,
          ''QUANTITY'', Nvl(d.quantity_ordered, 0),
          ''AMOUNT'', Nvl(d.amount_ordered, 0)
          ) ordered_on_Distribution,
  Decode (l.matching_basis,
          ''QUANTITY'', Nvl(d.quantity_delivered, 0),
          ''AMOUNT'', Nvl(d.amount_delivered, 0)
          ) Delivered_on_Distribution,
  Decode (l.matching_basis,
          ''QUANTITY'', Nvl(d.quantity_billed, 0),
          ''AMOUNT'', Nvl(d.amount_billed, 0)
          ) Billed_on_Distribution,
  h.po_header_id po_header_id,
  l.po_line_id po_line_id,
  s.line_location_id line_location_id,
  d.po_distribution_id po_distribution_id,
  l.matching_basis   Matching_basis,
  h.authorization_status  APPROVAL_STATUS,
  Decode (l.matching_basis,
          ''QUANTITY'', Decode( Nvl(d.quantity_billed, 0), 0,'''', ''Cancel Invoice now and recreate invoice after data fix. '') ,
          ''AMOUNT'', Decode( Nvl(d.amount_billed, 0), 0,'''', ''Cancel Invoice now and recreate invoice after data fix. '')
         )  || 
  Decode (l.matching_basis,
          ''QUANTITY'', Decode( Nvl(d.quantity_delivered, 0), 0,'''', ''Return receipt now and recreate Receipt after data fix''),
          ''AMOUNT'', Decode( Nvl(d.amount_delivered, 0), 0,'''', ''Return receipt now and recreate Receipt after data fix'')
          )  Action_Plan
  FROM 
po_headers_all h,
po_lines_all l,
po_line_locations_all s, 
po_distributions_All d,
po_system_parameters_All psp
WHERE
 /*joins start */
h.po_header_id = l.po_header_id
AND l.po_line_id = s.po_line_id
AND s.line_location_id = d.line_location_id
AND psp.org_id = h.org_id
AND NVL( s.CANCEL_FLAG, ''N'' ) <> ''Y''
AND NVL( s.CLOSED_CODE, ''OPEN'' ) <> ''FINALLY CLOSED''
/* joins end */
/*
For inventory and shop floor destinations, ACRF is always Y
For Expense destination,  ACRF depends on set up which i have fetched from 
po_system_parameters_All.
If expense accrual code is receipt, then expense destination should have ACRF the same as Receipt required flag
So the below conditions ensure that we get data whose ACRF is supposed to be Y but actually is N
*/
AND ( ( d.destination_type_code IN (''INVENTORY'', ''SHOP FLOOR'') AND (Nvl(d.accrue_on_receipt_flag, ''N'')  = ''N'' or Nvl(s.accrue_on_receipt_flag, ''N'') = ''N'') )
        OR
      ( d.destination_type_code = ''EXPENSE'' AND psp.EXPENSE_ACCRUAL_CODE = ''RECEIPT'' AND Nvl(s.receipt_required_flag, ''N'') = ''Y'' AND ( Nvl(s.accrue_on_receipt_flag, ''N'') = ''N'' or Nvl(d.accrue_on_receipt_flag, ''N'') = ''N'' ))
    )

/*the logic explained in above comments is true only if the following are true */
AND Nvl(s.CONSIGNED_FLAG, ''N'') = ''N'' 
AND s.shipment_type  <> ''PREPAYMENT''
AND d.award_id IS NULL
AND h.PCARD_ID IS NULL
AND h.po_header_id = ##$$DOCID$$##',
      p_title                  => 'Incorrect ACCRUE_ON_RECEIPT_FLAG -Correct Y Actual N',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The Accrue at Receipt flag is not correct and requires a datafix: Correct YES Actual NO.',
      p_solution               => 'See [1629692/KB197343] for solution.',
      p_success_msg            => 'No data corruption found.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: PRC_PO_WRONG_ACCRUE_ON_RECEIPT_FLAG_Y_N');



