debug('begin add_signature: PRC_PO_WRONG_QTY_CANCELED');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('##STYLE##quantity_cancelled'):= 'left,#333333,#ffd6cc,bold';
  add_signature(
      p_sig_repo_id            => '11558',
      p_sig_id                 => 'PRC_PO_WRONG_QTY_CANCELED',
      p_sig_sql                => 'SELECT poh.segment1 PO_NUMBER, 
       pod.po_header_id,
       pod.po_line_id,
       pod.line_location_id,
       poll.shipment_type,
       poll.cancel_flag,
       pod.po_distribution_id,
       pod.quantity_ordered,
       pod.quantity_cancelled,
       pod.quantity_billed,
       pod.quantity_delivered
FROM   po_distributions_all pod,
       po_line_locations_all poll,
       po_headers_all poh
WHERE  pod.po_header_id = poh.po_header_id
       AND poll.line_location_id = pod.line_location_id
       AND Nvl(poll.cancel_flag, ''N'') = ''Y''
       AND poll.shipment_type IN ( ''STANDARD'', ''BLANKET'' )
       AND Round(Nvl(pod.quantity_cancelled, 0), 15) <> ( 
           Round(Nvl(pod.quantity_ordered, 0), 15) -
           Greatest(Round(Nvl(pod.quantity_billed, 0), 15), Round(Nvl(pod.quantity_delivered, 0), 15)) )
       AND pod.po_header_id = ##$$DOCID$$##
       AND NOT EXISTS (SELECT 1
                       FROM   ap_invoice_distributions_all
                       WHERE  po_distribution_id = pod.po_distribution_id
                              AND creation_date > poll.cancel_date)',
      p_title                  => 'Incorrect Quantity Cancelled',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect quantity canceled at shipment and distribution level which can cause wrong total amount at PO Header.
',
      p_solution               => 'Apply Solution from [805547/KB256042]',
      p_success_msg            => 'No data corruption found.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: PRC_PO_WRONG_QTY_CANCELED');



debug('begin add_signature: PRC_PO_WRONG_QTY_COMMITTED');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('##STYLE##quantity_committed'):= 'left,#333333,#ffd6cc,bold';
  add_signature(
      p_sig_repo_id            => '11559',
      p_sig_id                 => 'PRC_PO_WRONG_QTY_COMMITTED',
      p_sig_sql                => 'SELECT  h.segment1    PO_NUMBER,
                h.po_header_id,
                h.authorization_status,
                h.document_creation_method CREATION_METHOD,
                h.org_id,
                l.line_num,
                l.po_line_id,
                l.last_update_date,
                l.quantity_committed
