debug('begin add_signature: 2776710_1_FUNDED_VALUES_EXIST_ON_NON_CLM_PROJECT_PO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '19176',
      p_sig_id                 => '2776710_1_FUNDED_VALUES_EXIST_ON_NON_CLM_PROJECT_PO',
      p_sig_sql                => 'select DECODE(LEAST(fileversion, ''120.27.12020000.29''), ''120.27.12020000.29'', ''DATAFIX ONLY'', ''PATCHFIX + DATAFIX'') Recommendation, 
filename, fileversion currentversion, ''120.27.12020000.29'' fixedversion,
poh.agent_id, pod.quantity_funded, pod.amount_funded, pod.CHANGE_IN_FUNDED_VALUE, pod.FUNDED_VALUE,
pod.po_distribution_id, pod.creation_date, pod.po_header_id, pod.po_line_id, pod.line_location_id,
pod.code_combination_id, pod.budget_account_id, pod.accrual_account_id, pod.variance_account_id, pod.destination_type_code, 
pod.destination_organization_id, pod.destination_subinventory,
pod.project_id, pod.task_id, pod.expenditure_type, pod.project_accounting_context, pod.expenditure_organization_id, pod.org_id 
from po_distributions_all pod, po_line_locations_all pll, po_headers_all poh,
  (select app_short_name, subdir, filename, fileversion
  from
    (select distinct
    af.filename,
    substr(af.filename, instr(af.filename, ''.'') + 1) ext,
    af.app_short_name, af.subdir,
      (
      select version
      from
        (select adv.file_id, adv.version
        from ad_file_versions adv
        order by
          to_number(version_segment1) desc,
          to_number(version_segment2) desc,
          to_number(version_segment3) desc,
          to_number(version_segment4) desc,
          to_number(version_segment5) desc,
          to_number(version_segment6) desc,
          to_number(version_segment7) desc,
          to_number(version_segment2) desc,
          to_number(version_segment9) desc,
          to_number(version_segment10) desc
          ) adv2
      where
        adv2.file_id = af.file_id
        and rownum = 1
      ) FileVersion
    from
    ad_files af,
    fnd_application fa
    where
    af.app_short_name = fa.application_short_name
    and (af.app_short_name = ''PO'')
    /* or fa.application_id = ##$$FK1$$## ) */
    and af.subdir not like ''admin%''
    and af.subdir not like ''help%''
    and af.subdir not like ''%driver%''
    and af.subdir not like ''%readme%''
    and substr(af.subdir, instr(af.subdir, ''/'', - 1) + 1) not in
    (
     select language_code
     from fnd_languages
     where
     installed_flag <> ''B''
     )
    and af.filename = ''pocit.o''
    ) FileVer
  ) InstanceFileVer
  where 
  PLL.LINE_LOCATION_ID = POD.LINE_LOCATION_ID
  and pod.project_id > 0 and pod.task_id > 0
  and (pod.quantity_funded is not null or pod.amount_funded is not null)
  and POD.po_header_id = poh.po_header_id
  and PO_CLM_INTG_GRP.is_clm_document(''PO'',poh.po_header_id) = ''N''
  and poh.po_header_id = ##$$DOCID$$##

and exists
(SELECT distinct fpo.profile_option_name, fpot.user_profile_option_name,
DECODE(fpov.level_id,10001,null,10002,null,10003,fndr.responsibility_name) plevelvalue,
DECODE(fpov.level_id,10001,''Site'',10002,''Application'',10003,''Responsibility'') plevel,
fpov.profile_option_value
FROM fnd_profile_option_values fpov,
fnd_profile_options fpo,
fnd_profile_options_tl fpot,
fnd_responsibility_tl fndr
WHERE fpov.profile_option_value = ''Y'' AND
fpo.profile_option_id = fpov.profile_option_id AND
fpo.profile_option_name = fpot.profile_option_name AND
TRUNC(fpo.start_date_active) <= SYSDATE AND
((fpot.user_profile_option_name = ''PA: Licensed to use Project Costing'' or fpot.user_profile_option_name = ''PA: Licensed to use Project Billing'')  AND
fpot.language = ''US'') AND
(
(fpov.level_id IN (10001))
or
(fpov.level_id IN (10002) and fpov.application_id = 201)
or
(fpov.level_id IN (10003) and fndr.application_id = 201 and fndr.responsibility_id = fpov.level_value)
)
AND
fndr.language = ''US'' and fndr.application_id = 201
)',
      p_title                  => 'Funded Values Incorrectly Populated on Non-CLM Project Charged Purchase Order',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'QUANTITY_FUNDED or AMOUNT_FUNDED at distribution level should be null, but instead are not null, on this Non-CLM Project Charged Purchase Order (PO).  This will result in Project Commitments not matching the PO Amount after running PRC: Refresh Project Summary Amounts, or running PRC: Update Project Summary Amounts.',
      p_solution               => 'Expand the row above to verify what action is needed to fix this project charged Purchase Order.  Profiles are setup to use Project Costing and therefore project charged purchase orders are impacted by this issue.  The row above will show the fix needed:  [ DATAFIX ONLY ] or [ PATCH FIX + DATAFIX ]

Upload this Analyzer output to an SR and mention [2776710/KB794165] with your datafix request to Support.

IMPORTANT:  Do not run the concurrent request - PRC: Refresh Project Summary Amounts (or PRC: Update Project Summary Amounts),  until after applying the patching solution from [2776710/KB794165].  It is critical that you apply the patching solution to avoid the issue described for Project Commitments.',
      p_success_msg            => 'There is no occurrence of funded values populated on Non-CLM Purchase Orders as described in [2776710/KB794165]',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: 2776710_1_FUNDED_VALUES_EXIST_ON_NON_CLM_PROJECT_PO');



