debug('begin add_signature: DATA_SINGLE_POREL1');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '427917.1';
   l_info('Script Name'):= 'poarsynf.sql';
  add_signature(
      p_sig_repo_id            => '2245',
      p_sig_id                 => 'DATA_SINGLE_POREL1',
      p_sig_sql                => 'SELECT poh.segment1,
           poll.po_header_id,
           poll.po_line_id,
           poll.line_location_id,
           poll.po_release_id,
           pol.order_type_lookup_code,
           nvl(poll.quantity_billed,0) qtyamt_billed_on_po_line_loc,
           sum(nvl(pod.quantity_billed,0)) qtyamt_billed_on_po_dist,
           round(nvl(poll.amount_billed,0),15) rndamtbilledpll, round(sum(nvl(pod.amount_billed,0)),15) rndamtbilledpod
    FROM po_line_locations_all poll,
         po_distributions_all pod,
         po_lines_all pol,
         po_headers_all poh
    WHERE poll.line_location_id=pod.line_location_id
    AND   pol.po_line_id= pod.po_line_id
    AND   pol.po_header_id = poh.po_header_id
    AND   nvl(pol.order_type_lookup_code,''QUANTITY'') IN (''AMOUNT'',''QUANTITY'')
    AND   nvl(poll.cancel_flag,''N'') <> ''Y''
    AND   nvl(poll.closed_code,''OPEN'') <> ''FINALLY CLOSED''
    AND   poll.shipment_type IN (''STANDARD'',''BLANKET'',''PLANNED'',''SCHEDULED'')
    AND   poh.po_header_id = ##$$DOCID$$##
    GROUP BY poh.segment1, poll.po_header_id, poll.po_line_id,
             poll.line_location_id, poll.po_release_id,
             pol.order_type_lookup_code, nvl(poll.quantity_billed,0), nvl(poll.amount_billed,0)
    HAVING   (round(nvl(poll.quantity_billed,0),15) <>  round(sum(nvl(pod.quantity_billed,0)),15) OR 
                     round(nvl(poll.amount_billed,0),15) <>  round(sum(nvl(pod.amount_billed,0)),15))
    UNION ALL
    SELECT poh.segment1,
           poll.po_header_id,
           poll.po_line_id,
           poll.line_location_id,
           poll.po_release_id,
           pol.order_type_lookup_code,
           nvl(poll.amount_billed,0) qtyamt_billed_on_po_line_loc,
           sum(nvl(pod.amount_billed,0)) qtyamt_billed_on_po_dist,
           round(nvl(poll.amount_billed,0),15) rndamtbilledpll, round(sum(nvl(pod.amount_billed,0)),15) rndamtbilledpod
    FROM po_line_locations_all poll,
         po_distributions_all pod,
         po_lines_all pol,
         po_headers_all poh
    WHERE poll.line_location_id=pod.line_location_id
    AND   pol.po_line_id= pod.po_line_id
    AND   pol.po_header_id = poh.po_header_id
    AND   nvl(pol.order_type_lookup_code,''QUANTITY'') IN (''FIXED PRICE'',''RATE'')
    AND   nvl(poll.cancel_flag,''N'') <> ''Y''
    AND   nvl(poll.closed_code,''OPEN'') <> ''FINALLY CLOSED''
    AND   poll.shipment_type in (''STANDARD'',''BLANKET'',''PLANNED'',''SCHEDULED'')
    AND   poh.po_header_id = ##$$DOCID$$##
    GROUP BY poh.segment1, poll.po_header_id, poll.po_line_id,
             poll.line_location_id, poll.po_release_id,
             pol.order_type_lookup_code, nvl(poll.amount_billed,0)
    HAVING  round(nvl(poll.amount_billed,0),15) <>
              round(sum(nvl(pod.amount_billed,0)),15)',
      p_title                  => 'Mismatched Quantity Billed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This document has a mismatch in the quantity billed between the shipments
     and the distributions.',
      p_solution               => 'Follow the solution instructions provided in [427917/KB563402]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: DATA_SINGLE_POREL1');



debug('begin add_signature: DATA_SINGLE_POREL2');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '454060.1';
  add_signature(
      p_sig_repo_id            => '2246',
      p_sig_id                 => 'DATA_SINGLE_POREL2',
      p_sig_sql                => 'SELECT poh.segment1,
           pod.po_header_id,
           pod.po_line_id,
           pod.line_location_id,
           pod.po_release_id,
           pod.po_distribution_id,
           nvl(pod.quantity_billed,0) qtybilled_on_po_dist,
           nvl(pod.amount_billed,0) amtbilled_on_po_dist,
           sum(nvl(aid.quantity_invoiced,0)) qtyinvoiced_on_ap_dist,
           sum(nvl(aid.amount,0)) amtinvoiced_on_ap_dist,
           pol.order_type_lookup_code
    FROM po_distributions_all pod,
         ap_invoice_distributions_all aid,
         po_lines_all pol,
         po_headers_all poh
    WHERE pod.po_distribution_id=aid.po_distribution_id
    AND pod.ENCUMBERED_FLAG <>''Y''
    AND   pod.po_line_id = pol.po_line_id
    AND   nvl(pol.order_type_lookup_code,''QUANTITY'') IN (''AMOUNT'',''QUANTITY'')
  AND aid.line_type_lookup_code IN (''ITEM'', ''ACCRUAL'',''IPV'',''RETROACCRUAL'',''RETROEXPENSE'')
--    AND   aid.line_type_lookup_code in (''ITEM'',''PREPAY'') 
    AND   poh.po_header_id = pol.po_header_id
    AND   poh.po_header_id = ##$$DOCID$$##
    GROUP BY poh.segment1, pod.po_header_id, pod.po_line_id,
             pod.line_location_id, pod.po_release_id,
             pod.po_distribution_id, nvl(pod.quantity_billed,0),
             nvl(pod.amount_billed,0), pol.order_type_lookup_code
    HAVING (round(nvl(pod.quantity_billed,0),15) <>
             round(sum(nvl(aid.quantity_invoiced,0)),15) OR
            round(nvl(pod.amount_billed,0),15) <>
              round(sum(nvl(aid.amount,0)),15))
    UNION ALL
    SELECT poh.segment1,
           pod.po_header_id,
           pod.po_line_id,
           pod.line_location_id,
           pod.po_release_id,
           pod.po_distribution_id,
           nvl(pod.quantity_billed,0) qtybilled_on_po_dist,
           nvl(pod.amount_billed,0) amtbilled_on_po_dist,
           sum(nvl(aid.quantity_invoiced,0)) qtyinvoiced_on_ap_dist,
           sum(nvl(aid.amount,0)) amtinvoiced_on_ap_dist,
           pol.order_type_lookup_code
    FROM po_distributions_all pod,
    ap_invoice_distributions_all aid,
    po_lines_all pol,
    po_headers_all poh
    WHERE pod.po_distribution_id=aid.po_distribution_id
    AND pod.ENCUMBERED_FLAG <>''Y''
    AND   pod.po_line_id = pol.po_line_id
    AND   nvl(pol.order_type_lookup_code,''QUANTITY'') IN (''FIXED PRICE'',''RATE'')
  AND aid.line_type_lookup_code IN (''ITEM'', ''ACCRUAL'',''IPV'',''RETROACCRUAL'',''RETROEXPENSE'')
--    AND   aid.line_type_lookup_code in (''ITEM'',''PREPAY'')
    AND   poh.po_header_id = pol.po_header_id
    AND   poh.po_header_id = ##$$DOCID$$##
    GROUP BY poh.segment1, pod.po_header_id, pod.po_line_id,
             pod.line_location_id, pod.po_release_id,
             pod.po_distribution_id, nvl(pod.quantity_billed,0),
             nvl(pod.amount_billed,0), pol.order_type_lookup_code
    HAVING round(nvl(pod.amount_billed,0),15) <>
             round(sum(nvl(aid.amount,0)),15)',
      p_title                  => 'Mismatched Quantity or Amounts Billed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This document has a mismatch in the quantity or amount billed
     between the shipments or distributions and the values on the invoice
     distributions in Payables',
      p_solution               => '<p>Follow the solution instructions provided in [454060/KB761838]. 
<p>For R12</p>
<ul>
<li>Apply the patch fix from [853382/KB605703]</li>
<li>Apply the generic datafix from [982072/KB679525]</li>
</ul>

If further assistance is needed in implementing the generic datafix, then a Service Request with Payables team should be created.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: DATA_SINGLE_POREL2');



debug('begin add_signature: DATA_SINGLE_POREL3');
   l_info('##SHOW_SQL##'):= 'Y';
