debug('begin add_signature: DATA_SINGLE_POREL4');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Bug Number'):= '14782923';
   l_info('Doc ID'):= '1379274.1';
   l_info('Script Name'):= 'poxpoaprvl.sql';
  add_signature(
      p_sig_repo_id            => '2248',
