debug('begin add_signature: DATA_SINGLE_POREL8');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '1280061.1';
  add_signature(
      p_sig_repo_id            => '2252',
      p_sig_id                 => 'DATA_SINGLE_POREL8',
      p_sig_sql                => 'SELECT pod.po_header_id,
           poh.segment1 po_number,
           poll.line_location_id,
           poll.ship_to_organization_id,
           pod.po_distribution_id,
           pod.destination_organization_id,
           null supply_source_id,
           null to_organization_id
    FROM po_distributions_all pod,
         po_line_locations_all poll,
         po_headers_all poh
    WHERE poh.po_header_id = ##$$DOCID$$##
    AND   poh.po_header_id = poll.po_header_id
    AND   pod.line_location_id = poll.line_location_id
    AND   pod.po_header_id = poll.po_header_id
    AND   pod.destination_organization_id != poll.ship_to_organization_id
    AND   nvl(poll.closed_code,''OPEN'') != ''FINALLY CLOSED''
    AND   nvl(poll.cancel_flag,''N'') != ''Y''
    UNION
    SELECT poh.po_header_id,
           poh.segment1,
           poll.line_location_id,
           poll.ship_to_organization_id,
           null,
           null,
           mtl.supply_source_id,
           mtl.to_organization_id
    FROM mtl_supply mtl,
         po_line_locations_all poll,
         po_headers_all poh
    WHERE poh.po_header_id = ##$$DOCID$$##
    AND   mtl.supply_type_code = ''PO''
    AND   mtl.po_line_location_id = poll.line_location_id
    AND   mtl.po_header_id = poll.po_header_id
    AND   mtl.to_organization_id != poll.ship_to_organization_id
    AND   nvl(poll.closed_code,''OPEN'') != ''FINALLY CLOSED''
    AND   nvl(poll.cancel_flag,''N'') != ''Y''
    AND   poh.po_header_id = poll.po_header_id',
      p_title                  => 'Ship To Organization Mismatch',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The ship to organization on the PO does not match the deliver to organization on the distributions or in mtl_supply. <br>
This can cause approved PO''''s not to be displayed in Inventory''''s Supply/Demand Detail window.',
      p_solution               => 'Please review [1280061/KB566661].<br>
To correct the data or if you need any other assistance implementing the solution, please create a Service Request with Purchase Order team referencing [1280061/KB566661].',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: DATA_SINGLE_POREL8');



debug('begin add_signature: DATA_SINGLE_PO5');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '465068.1';
  add_signature(
      p_sig_repo_id            => '2237',
      p_sig_id                 => 'DATA_SINGLE_PO5',
      p_sig_sql                => 'SELECT h.org_id,
           h.po_header_id,
           h.segment1 PO_NUMBER,
           ''Purchase Order'',
           pol.po_line_id,
           pol.line_num LINE_NUM
    FROM po_headers_all h,
         po_lines_all pol
    WHERE h.po_header_id = pol.po_header_id
    AND   h.po_header_id = ##$$DOCID$$##
    AND   EXISTS (
              SELECT ll.po_line_id
              FROM po_line_locations_all ll,
                   po_system_parameters_all sp
              WHERE ll.po_line_id = pol.po_line_id
              AND   ll.shipment_type in (''STANDARD'',''BLANKET'')
              AND   ll.po_release_id is null
              AND   ((ll.quantity - nvl(ll.quantity_cancelled,0)) *
                     (1 - nvl(ll.receive_close_tolerance,
                      nvl(sp.receive_close_tolerance,0))/100)) -
                    decode(sp.receive_close_code,
                      ''ACCEPTED'', nvl(ll.quantity_accepted,0),
                      ''DELIVERED'', (
                         SELECT sum(nvl(d1.quantity_delivered,0))
                         FROM po_distributions_all d1
                         WHERE d1.line_location_id= ll.line_location_id),
                      nvl(ll.quantity_received,0)) <= 0.000000000000001
              AND   ((ll.quantity - nvl(ll.quantity_cancelled,0)) *
                     (1 - nvl(ll.invoice_close_tolerance,
                            nvl(sp.invoice_close_tolerance,0))/100 )) -
                    nvl(ll.quantity_billed,0) <= 0.000000000000001
              AND   nvl(ll.closed_code,''OPEN'') IN (
                      ''OPEN'',''CLOSED FOR RECEIVING'',''CLOSED FOR INVOICE''))
    ORDER BY h.org_id, h.po_header_id, pol.po_line_id',
      p_title                  => 'Shipments Eligible to be Closed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This purchase order has shipments which are not closed but which are
     fully received and billed.',
      p_solution               => 'Follow the solution instructions provided in [465068/KB283108]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: DATA_SINGLE_PO5');



debug('begin add_signature: PORCVANLAZ_APPROVAL_STATUS_PO');
