debug('begin add_signature: EBS_MFG_PON_NEED_BY_DATE_VALIDATION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30758',
      p_sig_id                 => 'EBS_MFG_PON_NEED_BY_DATE_VALIDATION',
      p_sig_sql                => 'SELECT
    pah.document_number "Negotiation Number",
    paip.line_number       "Negotiation Line Num",
    pbip.bid_number        "Bid Number",
    pbip.line_number       "Bid Line Num",
    prh.segment1           "Requisition Number",
    prl.line_num           "Requisition Line Num",
    prl.need_by_date       "Requisition Line Need By Date",
    poh.segment1           "PO Number",
    pla.line_num           "PO Line Num",
    poll.shipment_num      "PO Shipment Num",
    poll.need_by_date      "PO Shipment Need By Date",
    prl.requisition_header_id,
    prl.requisition_line_id,
    prl.on_rfq_flag,
    poll.po_header_id,
    poll.po_line_id,
    poll.line_location_id,
    pah.auction_header_id
FROM
    po_line_locations_all       poll,
    po_lines_all                pla,
    po_headers_all              poh,
    po_requisition_lines_all    prl,
    po_requisition_headers_all  prh,
    pon_auction_headers_all     pah,
    pon_auction_item_prices_all paip,
    pon_bid_headers             pbh,
    pon_bid_item_prices         pbip
WHERE
        prh.requisition_header_id = prl.requisition_header_id
    AND prl.line_location_id = poll.line_location_id
    AND poll.po_header_id = poh.po_header_id
    AND poh.po_header_id = pla.po_header_id
AND pla.po_line_id like NVL(''##$$LINEID$$##'',''%'')
    AND poll.po_line_id = pla.po_line_id
    AND poll.po_header_id = pla.po_header_id
    AND pah.auction_header_id = paip.auction_header_id
    AND paip.auction_header_id = prl.auction_header_id
    AND prl.auction_line_number = paip.line_number
    AND pbh.auction_header_id = pah.auction_header_id
    AND pbh.bid_number = prl.bid_number
    AND pbh.auction_header_id = pbip.auction_header_id
    AND pbip.line_number = prl.bid_line_number
    AND paip.line_number = pbip.auction_line_number
    AND paip.auction_header_id = pbip.auction_header_id
    AND nvl(prl.on_rfq_flag, ''N'') = ''Y''
    AND prl.need_by_date <> poll.need_by_date
    AND nvl(poh.revision_num, 0) = 0
    AND poh.po_header_id = ##$$DOCID$$##
ORDER BY
    prl.line_num',
      p_title                  => 'Need By Date Validation Between Requisition Line(s) and Corresponding PO Shipments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'For one or more of the requisition line(s), Need-By Date is different from the corresponding PO Shipment.',
      p_solution               => 'Please review [3062150/KB513859] for details.',
      p_success_msg            => 'No action is needed. 
There are no requisition lines with Need-By Date different from corresponding PO shipment.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PON_NEED_BY_DATE_VALIDATION');



debug('begin add_signature: EBS_MFG_PO_PODOC_PO_CAN_POL_SHIP_BILL_GRT_REC');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '31317',
      p_sig_id                 => 'EBS_MFG_PO_PODOC_PO_CAN_POL_SHIP_BILL_GRT_REC',
      p_sig_sql                => 'SELECT POH.segment1 as "PO Number", POLL.po_header_id, POLL.po_line_id, POL.line_num, POLL.line_location_id, POLL.shipment_num, 
nvl(DECODE(POLL.shipment_type, ''PREPAYMENT'', POLL.quantity_financed, POLL.quantity_billed),0) as "QUANTITY_BILLED",
nvl(POLL.quantity_received,0) as "QUANTITY_RECEIVED"
FROM PO_LINE_LOCATIONS_ALL POLL, PO_LINES_ALL POL, PO_HEADERS_ALL POH
WHERE POLL.po_header_id =  ##$$DOCID$$## 
AND POLL.po_line_id = NVL(''##$$LINEID$$##'',POLL.po_line_id)
AND POL.po_header_id = POH.po_header_id
AND POH.po_header_id = POLL.po_header_id
AND POLL.po_line_id = POL.po_line_id
AND nvl(POLL.cancel_flag, ''N'') = ''N''
AND nvl(POLL.closed_code, ''OPEN'') != ''FINALLY CLOSED''
AND round(nvl(POLL.quantity,0),5) >= round(nvl(DECODE(POLL.shipment_type, ''PREPAYMENT'', POLL.quantity_financed, POLL.quantity_billed),0),5)
AND nvl(POLL.receipt_required_flag, ''Y'')!= ''N''
AND round(nvl(DECODE(POLL.shipment_type, ''PREPAYMENT'', POLL.quantity_financed, POLL.quantity_billed),0),5) > round(nvl(POLL.quantity_received,0),5)
AND POLL.value_basis IN (''QUANTITY'', ''AMOUNT'') ',
      p_title                  => 'PO_CAN_POL_SHIP_BILL_GRT_REC (Billed Qty > Received Qty)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'For one or more of the 3-way or 4-way purchase order line shipment(s), quantity billed is greater than received quantity.
',
      p_solution               => 'Cancel action is not allowed on these purchase order line shipments. 
Please review [423289/KB452192] for details.',
      p_success_msg            => 'No action is needed. 
',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_PODOC_PO_CAN_POL_SHIP_BILL_GRT_REC');



