debug('begin add_signature: PO_AMOUNT_ZERO_ON_GBPA_OR_CONTRACT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '17309',
      p_sig_id                 => 'PO_AMOUNT_ZERO_ON_GBPA_OR_CONTRACT',
      p_sig_sql                => 'select FixRequired.Action, pha.po_header_id, pha.type_lookup_code, pha.global_agreement_flag, pha.segment1, pha.org_id, pha.blanket_total_amount, pha.revision_num, pha.revised_date, 
pha.approved_date, pha.approved_flag, pha.authorization_status, pha.confirming_order_flag, pha.closed_date, pha.cancel_flag POHeader_cancel_flag, pla.cancel_flag PoLine_cancel_flag, pha.closed_code, pha.wf_item_type, pha.wf_item_key, pha.global_agreement_flag, 
pha.consigned_consumption_flag, pha.pending_signature_flag, pha.document_creation_method, pha.clm_document_number, pha.ame_approval_id, pha.clm_amount_released, pha.ame_transaction_type,
pla.po_line_id, pla.line_num, pla.org_id, pla.amount, pla.quantity, pla.clm_total_amount_ordered, pla.clm_total_quantity_ordered, pla.contract_id, pla.order_type_lookup_code, pla.purchase_basis
from po_headers_all pha, po_lines_all pla, 
  (select NVL(''Patch Fix + Data Fix Required'', ''Data Fix Required'') Action
   from 
     (select files.filename filename,files.subdir subdir, file_version.version version, rank()over(partition by files.filename, files.subdir
     order by file_version.version_segment1 desc, file_version.version_segment2 desc,file_version.version_segment3 desc, file_version.version_segment4 desc,file_version.version_segment5 desc,
     file_version.version_segment6 desc,file_version.version_segment7 desc, file_version.version_segment8 desc,file_version.version_segment9 desc, file_version.version_segment10 desc,
     file_version.translation_level desc) as rank1
     from ad_file_versions file_version, (select filename, app_short_name, subdir, file_id from ad_files where app_short_name=''PO'' and upper(filename) like upper(''POXCOC1B.pls'') ) files
     where ((version_segment3 = ''12020000'' and (to_number(version_segment2) < 42 or (to_number(version_segment2) = 42 and to_number(version_segment4) < 33))) 
            or
            (version_segment3 = ''12010000'' and (to_number(version_segment2) < 24 or (to_number(version_segment2) = 24 and to_number(version_segment4) < 39)))
           ) and files.file_id = file_version.file_id
     ) que
     where subdir = ''patch/115/sql'' and rank1 = 1) FixRequired
where 
  ( (pha.type_lookup_code = ''BLANKET'' AND NVL(pha.GLOBAL_AGREEMENT_FLAG, ''N'') = ''Y'')
      OR
    pha.type_lookup_code = ''CONTRACT''
  )
  AND NVL(pha.authorization_status,''INCOMPLETE'') <> ''INCOMPLETE''
  AND nvl(pha.closed_code,''OPEN'') <> ''FINALLY CLOSED''
  AND nvl(pha.cancel_flag,''N'') <> ''Y''
and pla.cancel_flag <> ''Y'' 
and pla.clm_total_amount_ordered = 0
and pla.po_line_id like NVL(''##$$LINEID$$##'',''%'')
and pla.from_header_id = pha.po_header_id
and pha.po_header_id = ##$$DOCID$$##',
      p_title                  => 'Incorrect Zero Amount Released On Global Blanket Agreement or Contract Agreement',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Global Blanket Agreement and/or Contract Agreement shows Released Amount as zero or incorrect value.',
      p_solution               => 'Review and implement the patch fix and data fix from [2414040/KB372512].',
      p_success_msg            => 'The agreement released amount does not have the issue described in [2414040/KB372512].',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: PO_AMOUNT_ZERO_ON_GBPA_OR_CONTRACT');



