debug('begin add_signature: PDOI_REQ_CHECK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '11039',
      p_sig_id                 => 'PDOI_REQ_CHECK',
      p_sig_sql                => 'select R.segment1 Requisition_Number, r.authorization_status Status, poh.document_type_code 
      ,rl.cancel_flag Cancelled, rl.closed_code Closed
      ,rl.line_num Req_Line_Number   , rl.REQS_IN_POOL_FLAG Eligible_for_PO   
      ,rl.line_location_id PO_Shipment_ID,  modified_by_agent_flag Edited_By_Buyer, at_sourcing_flag Sourced_Onto_PO
      ,rl.item_id Req_Item_ID, pol.item_id Po_Item_ID
from apps.po_req_distributions rd, 
     apps.po_requisition_lines rl,
     apps.po_requisition_headers r ,
     PO_HEADERS_INTERFACE poh, 
     PO_LINES_INTERFACE pol
where  1=1
and poh.interface_header_id = pol.interface_header_id
and pol.requisition_line_id = rl.requisition_line_id 
and rd.requisition_line_id = rl.requisition_line_id 
and rl.requisition_header_id = r.requisition_header_id 
and rl.requisition_line_id like NVL(''##$$LINEID$$##'',''%'')
and r.requisition_header_id = ##$$DOCID$$##
and r.creation_date > sysdate - 365
and --some condition exists that would fail it
(  nvl(rl.REQS_IN_POOL_FLAG,''N'') <> ''Y''     --PO_PDOI_REQ_NOT_POOL	    The referenced requisition line is not available in pool.
 or
   r.authorization_status <> ''APPROVED''     -- PO_PDOI_REQ_NOT_APRV	    The referenced requisition line is not approved.
 or 
   nvl(rl.cancel_flag,''N'') = ''Y''            --PO_PDOI_REQ_CANCEL	        The referenced requisition line is cancelled.  tested
 or
   rl.closed_code is not null               --PO_PDOI_REQ_NOT_OPEN	    The referenced requisition line is not open.
 or
   rl.modified_by_agent_flag = ''Y''         --PO_PDOI_REQ_MODFD	        The referenced requisition line is modified by another buyer. tested -- Check reqs modified_by_agent_flag is not Y
 or
   RL.at_sourcing_flag = ''Y''                --PO_PDOI_REQ_AT_SRC	    The referenced requisition line''s at_sourcing_flag is Y. It has been autocreated by another buyer.
 or 
   rl.line_location_id is not null           -- PO_PDOI_REQ_LINE_LOC	 The referenced requisition line''s line_location_id is not NULL.tested It has been autocreated by another buyer.
 or 
   nvl(rl.item_id,1) <> nvl(pol.item_id,1)    --PO_PDOI_REQ_ITEM_MIS	    Item does not match the item on the referenced requisition line.
 or
   nvl(rl.job_id,1) <> nvl(pol.job_id,1)       --PO_PDOI_REQ_JOB_MIS	        Job does not match the job on the referenced requisition line.
 or
   poh.document_type_code <> ''STANDARD''            --PO_PDOI_REQ_ON_SPO	Requisition reference can be given only on a Standard Purchase Order.
 or
    pol.interface_line_id in                                                       --go get any req line id''s in the interface 
   (Select distinct poll.interface_line_id  from PO_LINE_LOCATIONS_INTERFACE poll)  --should not be in this table if linked to req
  or 
    pol.interface_line_id in              
    (Select distinct pod.interface_line_id from PO_DISTRIBUTIONS_INTERFACE pod)  --should not be in this table if linked to req
)                                   ',
      p_title                  => 'PDOI Linked Requisition Check',
      p_fail_condition         => 'RSGT1',
      p_problem_descr          => 'The Requisition associated to the PDOI Line has issues that will cause it to fail Import',
      p_solution               => 'Review the data returned from the requisition and the PO and check [2053612/KB163871]',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: PDOI_REQ_CHECK');



debug('begin add_signature: 2776710_1_FUNDED_VALUES_EXIST_ON_NON_CLM_PROJECT_REQ');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '19181',
      p_sig_id                 => '2776710_1_FUNDED_VALUES_EXIST_ON_NON_CLM_PROJECT_REQ',
      p_sig_sql                => 'select DECODE(LEAST(fileversion, ''120.27.12020000.29''), ''120.27.12020000.29'', ''DATAFIX ONLY'', ''PATCHFIX + DATAFIX'') Recommendation, 
filename, fileversion currentversion, ''120.27.12020000.29'' fixedversion,
prd.distribution_id, prh.requisition_header_id, prh.creation_date,
prd.quantity_funded, prd.amount_funded, prd.CHANGE_IN_FUNDED_VALUE, prd.FUNDED_VALUE,
prd.distribution_id, prd.creation_date, prd.requisition_line_id,
prd.code_combination_id, prd.budget_account_id, prd.accrual_account_id, prd.variance_account_id, prl.destination_type_code, 
prl.destination_organization_id, prl.destination_subinventory,
prd.project_id, prd.task_id, prd.expenditure_type, prd.project_accounting_context, prd.expenditure_organization_id, prd.org_id 
from po_req_distributions_all prd, po_requisition_lines_all prl, po_requisition_headers_all prh,
  (select app_short_name, subdir, filename, fileversion
  from
    (select distinct
    af.filename,
    substr(af.filename, instr(af.filename, ''.'') + 1) ext,
    af.app_short_name, af.subdir,
      (
      select version
      from
        (select adv.file_id, adv.version
        from ad_file_versions adv
        order by
          to_number(version_segment1) desc,
          to_number(version_segment2) desc,
          to_number(version_segment3) desc,
          to_number(version_segment4) desc,
          to_number(version_segment5) desc,
          to_number(version_segment6) desc,
          to_number(version_segment7) desc,
          to_number(version_segment2) desc,
          to_number(version_segment9) desc,
          to_number(version_segment10) desc
          ) adv2
      where
        adv2.file_id = af.file_id
        and rownum = 1
      ) FileVersion
    from
    ad_files af,
    fnd_application fa
    where
    af.app_short_name = fa.application_short_name
    and (af.app_short_name = ''PO'')
    /* or fa.application_id = ##$$FK1$$## ) */
    and af.subdir not like ''admin%''
    and af.subdir not like ''help%''
    and af.subdir not like ''%driver%''
    and af.subdir not like ''%readme%''
    and substr(af.subdir, instr(af.subdir, ''/'', - 1) + 1) not in
    (
     select language_code
     from fnd_languages
     where
     installed_flag <> ''B''
     )
    and af.filename = ''pocit.o''
    ) FileVer
  ) InstanceFileVer
  where 
 (prd.quantity_funded is not null or prd.amount_funded is not null)
  and prd.project_id > 0 and prd.task_id > 0
  and 
  prd.requisition_line_id = prl.requisition_line_id
  and prl.requisition_header_id = prh.requisition_header_id
  and PO_CLM_INTG_GRP.is_clm_document(''REQUISITION'',prh.requisition_header_id) = ''N''
  and prh.requisition_header_id = ##$$DOCID$$##

and exists
(SELECT distinct fpo.profile_option_name, fpot.user_profile_option_name,
DECODE(fpov.level_id,10001,null,10002,null,10003,fndr.responsibility_name) plevelvalue,
DECODE(fpov.level_id,10001,''Site'',10002,''Application'',10003,''Responsibility'') plevel,
fpov.profile_option_value
FROM fnd_profile_option_values fpov,
fnd_profile_options fpo,
fnd_profile_options_tl fpot,
fnd_responsibility_tl fndr
WHERE fpov.profile_option_value = ''Y'' AND
fpo.profile_option_id = fpov.profile_option_id AND
fpo.profile_option_name = fpot.profile_option_name AND
TRUNC(fpo.start_date_active) <= SYSDATE AND
((fpot.user_profile_option_name = ''PA: Licensed to use Project Costing'' or fpot.user_profile_option_name = ''PA: Licensed to use Project Billing'')  AND
fpot.language = ''US'') AND
(
(fpov.level_id IN (10001))
or
(fpov.level_id IN (10002) and fpov.application_id = 201)
or
(fpov.level_id IN (10003) and fndr.application_id = 201 and fndr.responsibility_id = fpov.level_value)
)
AND
fndr.language = ''US'' and fndr.application_id = 201 -- Replace with responsibility name used for iProcurement
)',
      p_title                  => 'Funded Values Incorrectly Populated on Non-CLM Project Charged Imported Requisition',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'QUANTITY_FUNDED or AMOUNT_FUNDED at distribution level should be null, but instead are not null, on this Non-CLM Project Charged Requisition.  This will result in Project Commitments not matching the PO Amount after Autocreating the requisition to Purchase Order and running PRC: Refresh Project Summary Amounts, or running PRC: Update Project Summary Amounts.',
      p_solution               => 'Expand the row above to verify what action is needed to fix this project charged Requisition.  Profiles are setup to use Project Costing and therefore project charged purchase orders autocreated from requisitions like this are impacted by this issue.  The row above will show the fix needed:  [ DATAFIX ONLY ] or [ PATCH FIX + DATAFIX ]

Upload this Analyzer output to an SR and mention [2776710/KB794165] with your datafix request to Support.

IMPORTANT:  Do not run the concurrent request - PRC: Refresh Project Summary Amounts (or PRC: Update Project Summary Amounts),  until after applying the patching solution from [2776710/KB794165].  It is critical that you apply the patching solution to avoid the issue described for Project Commitments.',
      p_success_msg            => 'There is no occurrence of funded values populated on Non-CLM Requisitions as described in [2776710/KB794165]',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: 2776710_1_FUNDED_VALUES_EXIST_ON_NON_CLM_PROJECT_REQ');



debug('begin add_signature: PO_CANNOT_RECEIVE_AFTER_CANCEL_IR_FOR_ISO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '19755',
      p_sig_id                 => 'PO_CANNOT_RECEIVE_AFTER_CANCEL_IR_FOR_ISO',
      p_sig_sql                => 'SELECT    DISTINCT
        req.requisition_line_id, req.cancel_flag, lin.shipment_line_status_code
  ,    prh.requisition_header_id
  FROM    
 apps.rcv_shipment_headers    hea
  ,    apps.rcv_shipment_lines lin
  ,    apps.po_requisition_lines_all    req
  ,    apps.po_req_distributions_all    prd
  ,    apps.po_requisition_headers_all prh
  ,    apps.oe_order_headers_all    ooha
  ,    apps.oe_order_lines_all oola
  ,    apps.mtl_parameters    mp1
  ,    apps.mtl_parameters    mp2
  ,    apps.mtl_system_items    msi
  WHERE    1=1
  AND    hea.shipment_header_id           = lin.shipment_header_id
  AND    lin.requisition_line_id        = req.requisition_line_id
  AND    req.requisition_line_id        = prd.requisition_line_id
  AND    lin.shipment_line_status_code  <> ''FULLY RECEIVED''
  AND    receipt_source_code           = ''INTERNAL ORDER''
  and    req.item_id           = msi.inventory_item_id
  and    msi.organization_id           = lin.to_organization_id
  AND    req.requisition_line_id        = oola.source_document_line_id
  AND    ooha.header_id           = oola.header_id
  AND    req.requisition_header_id      = prh.requisition_header_id
  and  lin.from_organization_id = mp1.organization_id
  and  lin.to_organization_id = mp2.organization_id
  and  req.cancel_flag = ''Y''
 and req.requisition_line_id like NVL(''##$$LINEID$$##'',0)
  and req.requisition_header_id = ##$$DOCID$$##',
      p_title                  => 'Cannot Complete Receipt After Canceling Internal Requisition Associated To Internal Sales Order',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Attempting to Receive Items for Internal Sales Order after Canceling the associated Internal Requisition results in error as described in [2060502/KB404977]:<br>
 Error : RVTII-077: ORA-01476: divisor is equal to zero',
      p_solution               => 'Implement the patching solution from [2006585/KB271669] to prevent the issue on future documents.  <br>
If a datafix is required for existing documents, request a datafix for corresponding [2060502/KB404977] from Oracle Support through a Service Request.',
      p_success_msg            => 'This requisition is not a canceled Internal Requisitions (IR) having pending receipts not performed against the associated Internal Sales Order (ISO).',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: PO_CANNOT_RECEIVE_AFTER_CANCEL_IR_FOR_ISO');



debug('begin add_signature: PRC_IR-ISO_QTY_NOT_SYNCHRONIZED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22039',
      p_sig_id                 => 'PRC_IR-ISO_QTY_NOT_SYNCHRONIZED',
      p_sig_sql                => 'SELECT prh.segment1 req_number,prl.requisition_line_id req_line_id,prl.line_num req_line_num,prl.quantity req_quantity, 
  (SELECT Sum(ordered_quantity)
   FROM oe_order_lines_all
   WHERE source_document_line_id= prl.requisition_line_id
   AND SOURCE_DOCUMENT_TYPE_ID = 10) iso_quantity
FROM po_requisition_lines_all prl, po_requisition_headers_all prh
WHERE prh.requisition_header_id =##$$DOCID$$##
AND prl.requisition_header_id=prh.requisition_header_id
AND Nvl(prl.cancel_flag,''N'') = ''N''
AND Nvl(prl.transferred_to_oe_flag,''N'') = ''Y''
AND Nvl(prl.closed_code,''OPEN'') = ''OPEN''
AND Nvl(prl.quantity,0) - Nvl(quantity_delivered,0) > 0
AND Nvl(prl.quantity,0) <>
  (SELECT Sum(ordered_quantity)
  FROM oe_order_lines_all
  WHERE source_document_line_id= prl.requisition_line_id
  AND SOURCE_DOCUMENT_TYPE_ID = 10)
AND prl.requisition_line_id like NVL(''##$$LINEID$$##'',''%'')',
      p_title                  => 'IR-ISO Quantity Not Synchronized',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect quantity for internal requisition that is not synchronized with internal sales order quantity.',
      p_solution               => 'Implement the patching solution from [2620037/KB510825] to prevent the issue on future documents.
If a datafix is required for existing documents, request a datafix for corresponding [2620037/KB510825] from Oracle Support through a Service Request.',
      p_success_msg            => 'No data corruption found.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: PRC_IR-ISO_QTY_NOT_SYNCHRONIZED');



debug('begin add_signature: EBS_MFG_PRC_PODOC_GBPA_PRICE_OVERRIDE_DIFF_REQLINE_UNIT_PIRCE');
