debug('begin add_signature: EBS_MFG_PO_PO_PODOC_RCV_VS_AP_AMT_QTY_BILLED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '26546',
      p_sig_id                 => 'EBS_MFG_PO_PO_PODOC_RCV_VS_AP_AMT_QTY_BILLED',
      p_sig_sql                => 'SELECT /*+  ordered use_nl(aid, rcv) */
          aid.rcv_transaction_id,
          aid.invoice_id,
          rcv.po_header_id, rcv.po_release_id, rcv.po_line_id, rcv.po_distribution_id,
          nvl(rcv.amount_billed,0) rcv_amount,
          nvl(rcv.quantity_billed,0) rcv_quantity, nvl(aid.amount,0) inv_amount, nvl(aid.quantity_invoiced,0) inv_quantity_invoiced
   FROM ap_invoice_distributions_all aid,
        rcv_transactions rcv
   WHERE
     EXISTS (
           SELECT /*+ no_unnest ordered use_nl(aid2, rcv2) */ 1
           FROM ap_invoice_distributions_all aid2,
                rcv_transactions rcv2
           WHERE aid2.rcv_transaction_id = aid.rcv_transaction_id
           AND   rcv2.transaction_id = aid2.rcv_transaction_id
           AND   aid2.rcv_transaction_id is not null
           AND   aid2.line_type_lookup_code IN (''ITEM'',''ACCRUAL'',''IPV'',''PREPAY'')
           GROUP BY nvl(rcv2.quantity_billed,0), nvl(rcv2.amount_billed,0),
                    aid2.rcv_transaction_id
           HAVING ((sum(nvl(aid2.quantity_invoiced,0)) <> nvl(rcv2.quantity_billed,0) OR
                    sum(nvl(aid2.amount,0)) <> nvl(rcv2.amount_billed,0))
           AND     sum(nvl(aid2.quantity_invoiced,0)) >= 0
           AND     sum(nvl(aid2.amount,0)) >=0 ))
     AND   aid.line_type_lookup_code IN (''ITEM'',''ACCRUAL'',''IPV'',''PREPAY'')
     AND   aid.rcv_transaction_id is not null
     AND   aid.rcv_transaction_id = rcv.transaction_id
AND
(
(rcv.po_header_id = ##$$DOCID$$##
AND rcv.po_release_id is null
AND ''##DOCTYPE##'' = ''PO''
AND rcv.po_line_id like NVL(''##$$LINEID$$##'',''%''))
or
(rcv.po_header_id = ##$$DOCID$$##
AND rcv.po_release_id = nvl(''##$$RELID$$##'',0)
AND rcv.po_line_location_id like NVL(''##$$LINEID$$##'',''%'')
AND ''##DOCTYPE##'' = ''REL'')
)',
      p_title                  => 'Receipt vs Invoice Amount Quantity Billed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Receiving distributions out of synch with AP distributions for quantity or amount billed<br/><strong>Impact Area(s): </strong>Invoice Discard',
      p_solution               => 'Review [982072/KB679525] for a datafix solution.
Contact Oracle Payables Support if additional clarification is needed.',
      p_success_msg            => 'There is no difference between the receiving and AP distributions for quantity or amount billed.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PO_PO_PODOC_RCV_VS_AP_AMT_QTY_BILLED');



