debug('begin add_signature: EBS_MFG_PO_APPRVL_CHARGEABLE_FLAG_FOR_TASK_ID');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '28042',
      p_sig_id                 => 'EBS_MFG_PO_APPRVL_CHARGEABLE_FLAG_FOR_TASK_ID',
      p_sig_sql                => 'SELECT
    pol.line_num,
    poll.shipment_num,
    pod.distribution_num,
    pap.name,
    pap.segment1,
    pat.chargeable_flag chargeable_flag,
    pat.task_id,
    pat.*
FROM
