debug('begin add_signature: EBS_MFG_PO_PODOC_BLANKET_RELEASES_LINKED_TO_BPA');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '28614',
      p_sig_id                 => 'EBS_MFG_PO_PODOC_BLANKET_RELEASES_LINKED_TO_BPA',
      p_sig_sql                => 'select
poh.segment1 PO_NUM,
por.RELEASE_NUM,
por.PO_RELEASE_ID,
pov.VENDOR_NAME,
pvs.VENDOR_SITE_CODE,
poh.AUTHORIZATION_STATUS BPA_STATUS,
por.AUTHORIZATION_STATUS REL_STATUS,
por.CLOSED_CODE REL_CLOSED_CODE,
poll.cancel_flag,
poll.QUANTITY,
poll.QUANTITY_RECEIVED,
poll.QUANTITY_BILLED,
poll.QUANTITY_CANCELLED,
poll.AMOUNT,
poll.AMOUNT_RECEIVED,
poll.AMOUNT_BILLED,
poll.PRICE_OVERRIDE,
poll.closed_code SHIPMENT_STATUS
from po_headers_all poh,
po_vendors pov,
po_vendor_sites_all pvs,
PO_RELEASES_ALL por,
PO_LINES_ALL pol,
po_line_locations_all poll
where poh.PO_HEADER_ID = ##$$DOCID$$##
AND poll.po_line_id like NVL(''##$$LINEID$$##'',''%'')
and poh.po_header_id = pol.po_header_id
and pol.po_header_id = por.po_header_id
and por.po_header_id = poll.po_header_id
and poh.vendor_id = pov.vendor_id
and pov.vendor_id = poh.vendor_id
and poh.vendor_site_id = pvs.vendor_site_id
and pvs.vendor_site_id = poh.vendor_site_id
and pol.PO_LINE_ID = poll.PO_LINE_ID
and poh.org_id = pol.org_id
and pol.org_id = poll.org_id
and poll.org_id = por.org_id
and por.PO_RELEASE_ID = poll.PO_RELEASE_ID
ORDER BY por.creation_date DESC',
      p_title                  => 'Blanked Releases linked to Local BPA',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This is the list of all Blanket Releases linked to this BPA.',
