DECODE(c.name, ''MISC'', ''Miscellaneous'', ''Vendor'', ''To Supplier'', ''Buyer'', ''To Buyer'', ''Receiver'', ''To Receiver'', ''Approver'', ''To Approver'', ''REQ Internal'', ''Internal to Requisition'', ''UNKNOWN'') AttentionTo,
DECODE(d.datatype_id, 1, ''Short text'', 2, ''Long text'', 5, ''Web Page'', 6, ''File'', 7, ''Document reference'', ''UNKNOWN'') Type,
dtl.description, dtl.file_name, dtl.media_id, dtl.datatype_name, dtl.publish_flag, dtl.usage_type_descr
FROM fnd_documents d,
fnd_document_categories c,
fnd_attached_documents ad,
fnd_documents_vl dtl,
po_requisition_headers_all h
WHERE 
d.category_id = c.category_id(+)
AND d.document_id = ad.document_id
AND ad.entity_name in (''REQ_HEADERS'')
AND ad.pk1_value = to_char(h.requisition_header_id)
AND h.requisition_header_id = ##$$DOCID$$##
AND d.document_id = dtl.document_id
union all
SELECT ad.entity_name, ad.seq_num Seq , ad.pk1_value,
DECODE(c.name, ''MISC'', ''Miscellaneous'', ''Vendor'', ''To Supplier'', ''Buyer'', ''To Buyer'', ''Receiver'', ''To Receiver'', ''Approver'', ''To Approver'', ''REQ Internal'', ''Internal to Requisition'', ''UNKNOWN'') AttentionTo,
DECODE(d.datatype_id, 1, ''Short text'', 2, ''Long text'', 5, ''Web Page'', 6, ''File'', 7, ''Document reference'', ''UNKNOWN'') Type,
dtl.description, dtl.file_name, dtl.media_id, dtl.datatype_name, dtl.publish_flag, dtl.usage_type_descr
FROM fnd_documents d,
fnd_document_categories c,
fnd_attached_documents ad,
fnd_documents_vl dtl,
po_requisition_lines_all l
WHERE d.category_id = c.category_id
AND d.document_id = ad.document_id
AND ad.entity_name in (''REQ_LINES'',''REQ_LINE_CHANGES'')
AND ad.pk1_value = to_char(l.requisition_line_id)
AND l.requisition_line_id like NVL(''##$$LINEID$$##'',''%'')
AND l.requisition_header_id = ##$$DOCID$$##
AND d.document_id = dtl.document_id
)
order by entity_name, seq',
      p_title                  => 'Requisition Header, Line, and Line Change Attachments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Document Attachments',
      p_solution               => 'Requisition Header, Line, and Line Change attachments',
      p_success_msg            => 'No attachments found at the Header, Line, or Shipment level for this Document',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_PODOC_REQ_ATTACHMENTS');



