      p_sig_sql                => 'SELECT DISTINCT
    mtl.ORGANIZATION_CODE inv_org_code,
    mtl.ORGANIZATION_ID inv_org_id,
    mtl.MATERIAL_ACCOUNT,
    mtl.PURCHASE_PRICE_VAR_ACCOUNT,
    mtl.INVOICE_PRICE_VAR_ACCOUNT,
    mtl.AP_ACCRUAL_ACCOUNT,
    mtl.ENCUMBRANCE_ACCOUNT,
    mtl.PROCESS_ENABLED_FLAG,
    mtl.PROCESS_ORGN_CODE,
    mtl.LCM_ENABLED_FLAG
FROM
    PO_REQUISITION_LINES_ALL pll
    JOIN MTL_PARAMETERS_VIEW mtl
      ON (pll.DESTINATION_ORGANIZATION_ID = mtl.ORGANIZATION_ID
          OR pll.SOURCE_ORGANIZATION_ID = mtl.ORGANIZATION_ID)
WHERE
    pll.REQUISITION_HEADER_ID = ##$$DOCID$$##
    and pll.REQUISITION_LINE_ID like NVL(''##$$LINEID$$##'',''%'')',
