debug('begin add_signature: PO_USE_PDOI_AUTOCREATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10374',
      p_sig_id                 => 'PO_USE_PDOI_AUTOCREATE',
      p_sig_sql                => 'SELECT user_profile_option_name "Profile Option",
a.profile_option_value "Profile Value",
DECODE(a.level_id, 10001, ''Site'',
10002, ''Application'',
10003, ''Responsibility'',
10004, ''User'') "Level",
DECODE(a.level_id, 10001, ''Site'',
10002, b.application_short_name,
10003, c.responsibility_name,
10004, d.user_name) "Level Value",
c.responsibility_id
FROM fnd_profile_option_values a,
fnd_application b,
fnd_responsibility_tl c,
fnd_user d,
fnd_profile_options e,
fnd_profile_options_tl t
WHERE a.profile_option_id = e.profile_option_id
AND a.level_value = b.application_id(+)
AND a.level_value = c.responsibility_id(+)
AND a.level_value = d.user_id(+)
AND t.profile_option_name = e.profile_option_name
AND t.LANGUAGE = ''US''
AND nvl(c.LANGUAGE,''US'') = ''US''
AND e.profile_option_name IN (''PO_USE_PDOI_AUTOCREATE'')
AND (a.profile_option_value = ''N'' and a.level_id = 10001)
ORDER BY e.profile_option_name,
a.level_id DESC',
      p_title                  => 'PO: Use PDOI Autocreate',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p>Profile PO: Use PDOI Autocreate is set to No.&nbsp;</p>
<p>The Import Standard Purchase Orders will use the new codeline - but the Autocreate processes will use the older - original Autocreate codeline.</p>
<p>This is why the profile can impact the Autocreate process, as it determines if the newer codeline or older codeline is being used. Oracle Purchasing Development has recommended that the profile should be set to Yes or left NULL - so as to use the new codeline.</p>',
      p_solution               => 'See [2243412/KB364926] - What is the Profile PO: Use PDOI Autocreate Used For?',
      p_success_msg            => 'The profile is NULL or Yes - the new codeline is used - the merged codeline - for both the Autocreate process and the Import Standard Purchase Order process. This is the recommended setting by Oracle Purchasing Development.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: PO_USE_PDOI_AUTOCREATE');



