debug('begin add_signature: POA_TABLESPACE_CHECK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1693',
      p_sig_id                 => 'POA_TABLESPACE_CHECK',
      p_sig_sql                => 'SELECT s.segment_name object_name,
           s.owner,
           s.tablespace_name tablespace,
           s.segment_type object_type,
           s.extents extents,
           s.max_extents max_extents,
           s.next_extent/1024/1024 next_extent,
           max(fs.bytes)/1024/1024 max,
           sum(fs.bytes)/1024/1024 free
    FROM dba_segments     s,
         dba_free_space   fs
    WHERE s.segment_type IN (''TABLE'',''INDEX'')
    AND   (s.segment_name like ''PO\_%'' escape ''\'' OR s.segment_name like ''ICX\_%'' escape ''\'')
    AND   fs.tablespace_name = s.tablespace_name
    GROUP BY s.tablespace_name, s.owner, s.segment_type,
           s.segment_name, s.extents, s.max_extents, s.next_extent
    HAVING (s.extents >= (s.max_extents - 2) OR
            s.next_extent > max(fs.bytes))
    ORDER BY extents desc',
      p_title                  => 'Potential Space and Extents Issues',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The objects listed above are either approaching their
     maximum number or extents, or have a next extent size
     that is larger than the largest available block of
     free space in the tablespace.',
      p_solution               => '<ul> <li>Review items indicated and increase the max extents or add
    additional data files to the tablespace as required</li></ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: POA_TABLESPACE_CHECK');



