-- MAIN ENTRY POINT
---------------------------------
PROCEDURE main(
            p_org_id                       IN NUMBER      DEFAULT NULL
           ,p_doc_type                     IN VARCHAR2    DEFAULT NULL
           ,p_doc_number                   IN VARCHAR2    DEFAULT NULL
           ,p_doc_release                  IN NUMBER      DEFAULT NULL
           ,p_req_line_number              IN NUMBER      DEFAULT NULL
           ,p_po_line_number               IN NUMBER      DEFAULT NULL
           ,p_bpa_line_number              IN NUMBER      DEFAULT NULL
           ,p_rel_line_number              IN NUMBER      DEFAULT NULL
           ,p_include_apps_check           IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 200
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

 IS

  l_sql_result VARCHAR2(1);
  l_step       VARCHAR2(5);
  --l_analyzer_end_time   TIMESTAMP;

BEGIN

  l_step := '1';
  initialize_globals;

  -- Workaround for handling debugging before file init
  g_debug_mode := nvl(p_debug_mode, 'Y');
  g_params_string := '';



  l_step := '10';
  initialize_files;

  analyzer_title := 'Procurement Document Analyzer';
  analyzer_title := regexp_replace('EBS ' || analyzer_title, '(\S+\s)\1', '\1', 1, 0, 'i');  -- EBSAF-243

  l_step := '15';
   validate_parameters(
     p_org_id                       => p_org_id
    ,p_doc_type                     => p_doc_type
    ,p_doc_number                   => p_doc_number
    ,p_doc_release                  => p_doc_release
    ,p_req_line_number              => p_req_line_number
    ,p_po_line_number               => p_po_line_number
    ,p_bpa_line_number              => p_bpa_line_number
    ,p_rel_line_number              => p_rel_line_number
    ,p_include_apps_check           => upper(p_include_apps_check)
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  l_step := '20';
  set_cloud_flag;

  l_step := '23';
  set_snap_days;

  l_step := '25';
  print_page_header;

  l_step := '30';
  print_rep_header(analyzer_title);
  --print_execdetails;
  print_feedback;
  print_parameters;
  print_whatsnew;

  l_step := '40';
  load_signatures;

  l_step := '45';
  create_hyperlink_table;

  l_step := '50';
  initialize_hidden_xml;

  -- Start of Sections and signatures
  l_step := '60';
  debug('begin section: Main Section');
  -- Print the menu of the section screen
  start_main_section;

debug('begin section: Purchasing_Doc_Data');
start_section('Purchasing Data', 'Purchasing_Doc_Data');
   IF p_doc_type = 'PO' THEN
      set_item_result(run_stored_sig('PO - PO_HEADERS_ALL'));
      set_item_result(run_stored_sig('PO - PO_LINES_ALL'));
      set_item_result(run_stored_sig('PO - PO_LINE_LOCATIONS_ALL'));
      set_item_result(run_stored_sig('PO - PO_DISTRIBUTIONS_ALL'));
      set_item_result(run_stored_sig('PO - PO_ACTION_HISTORY'));
      set_item_result(run_stored_sig('PO - PO_HEADERS_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('PO - PO_LINES_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('PO - PO_LINE_LOCATIONS_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('PO - PO_DISTRIBUTIONS_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('EBS_MFG_PO_APPRVL_CHARGEABLE_FLAG_FOR_TASK_ID'));
      set_item_result(run_stored_sig('EBS_MFG_PO_DOC_ATTACHMENTS'));
      IF p_doc_type IN ('PO','BPA') THEN
         set_item_result(run_stored_sig('EBS_MFG_APPRVL_PO_SUPPLIER_DOES_NOT_HAVE_A_SUPPLIER_SITE_SPECIFIED'));
      END IF;
      set_item_result(run_stored_sig('EBS_MFG_PO_PODOC_PO_DRAFTS'));
      IF substr(g_sql_tokens('##$$REL$$##'),1,4) = '12.2' THEN
         set_item_result(run_stored_sig('EBS_MFG_PO_GINV_PO_HEADERS_ALL_EXT_B'));
         set_item_result(run_stored_sig('EBS_MFG_GINV_EXTRACT_OF_PO_LINES_ALL_EXT_B'));
         set_item_result(run_stored_sig('EBS_MFG_GINV_PO_DISTRIBUTIONS_ALL_EXT_B'));
         set_item_result(run_stored_sig('EBS_MFG_GINV_PO_LINE_LOCATIONS_ALL_EXT_B'));
         set_item_result(run_stored_sig('PO_AMOUNT_ZERO_ON_GBPA_OR_CONTRACT'));
         set_item_result(run_stored_sig('2776710_1_FUNDED_VALUES_EXIST_ON_NON_CLM_PROJECT_PO'));
      END IF;
      IF g_sql_tokens('##$$IS_BREQ$$##') = 'Y' THEN
         set_item_result(run_stored_sig('PO - PO_REQUISITION_HEADERS_ALL'));
         set_item_result(run_stored_sig('PO - PO_REQUISITION_LINES_ALL'));
         set_item_result(run_stored_sig('PO - PO_REQ_DISTRIBUTIONS_ALL'));
         set_item_result(run_stored_sig('PO - PO_ACTION_HISTORY_REQ'));
      END IF;
      set_item_result(run_stored_sig('PO - PO_CHARGE_ACCOUNT'));
      set_item_result(run_stored_sig('PO - PO_BUDGET_ACCOUNT'));
      set_item_result(run_stored_sig('PO - PO_ACCRUAL_ACCOUNT'));
      set_item_result(run_stored_sig('PO - PO_VARIANCE_ACCOUNT'));
      set_item_result(run_stored_sig('PO -  MTL_PARAMETERS_VIEW - PO SHIPMENT SHIP TO ORG'));
      set_item_result(run_stored_sig('PO - MTL_SUPPLY_PO'));
      set_item_result(run_stored_sig('PO - MTL_SYSTEM_ITEMS_B'));
      set_item_result(run_stored_sig('PO - ZX_LINES'));
      set_item_result(run_stored_sig('PO - ZX_LINES_DET_FACTORS'));
      set_item_result(run_stored_sig('PRC_ZX_REC_NREC_DIST'));
      set_item_result(run_stored_sig('EBS_MFG_PRC_IPDIAGCA_CHANGE_REQUEST_CONSOLIDATED_DATA_COLLECTION'));
      set_item_result(run_stored_sig('PO - PO_CHANGE_REQUESTS'));
      set_item_result(run_stored_sig('EBS_MFG_PO_PODOC_PO_ACCEPTANCES'));
      set_item_result(run_stored_sig('EBS_MFG_PO_IPDIAGCA_ACTIVE_CHANGE_REQUEST_DATA'));
      IF substr(g_sql_tokens('##$$REL$$##'),1,4) = '12.1' THEN
         set_item_result(run_stored_sig('PO_USE_PDOI_AUTOCREATE'));
      END IF;
      set_item_result(run_stored_sig('PO_CREATED_BWC_ATTACHMENT_SUPPLIER_SITE_REMOVED'));
      set_item_result(run_stored_sig('PO - PO_LINE_LOCATIONS_DROP_SHIP'));
      set_item_result(run_stored_sig('EBS_MFG_PO_AP_SUPPLIER_SUPPLIER_SITES_TAX'));
   END IF;
   IF p_doc_type = 'REL' THEN
      set_item_result(run_stored_sig('REL-PO_HEADERS_ALL'));
      set_item_result(run_stored_sig('REL- PO_LINES_ALL'));
      set_item_result(run_stored_sig('REL-BPA-PO_LINE_LOCATIONS_ALL'));
      set_item_result(run_stored_sig('REL-BPA-PO_ACTION_HISTORY'));
      set_item_result(run_stored_sig('REL-PO_LINES_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('REL-PO_LINE_LOCATIONS_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('REL- PO_RELEASES_ALL'));
      set_item_result(run_stored_sig('REL- PO_LINE_LOCATIONS_ALL'));
      set_item_result(run_stored_sig('REL-PO_DISTRIBUTIONS_ALL'));
      set_item_result(run_stored_sig('REL-PO_ACTION_HISTORY'));
      set_item_result(run_stored_sig('REL- PO_RELEASES_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('REL- PO_LINE_LOCATIONS_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('REL-PO_DISTRIBUTIONS_ARCHIVE_ALL'));
      set_item_result(run_stored_sig('EBS_MFG_PODOC_REL_ATTACHMENTS'));
      IF g_sql_tokens('##$$IS_BREQ$$##') = 'Y' THEN
         set_item_result(run_stored_sig('REL-PO_REQUISITION_HEADERS_ALL'));
         set_item_result(run_stored_sig('REL-PO_REQUISITION_LINES_ALL'));
         set_item_result(run_stored_sig('REL-PO_REQ_DISTRIBUTIONS_ALL'));
         set_item_result(run_stored_sig('REL-REQ-PO_ACTION_HISTORY'));
      END IF;
      set_item_result(run_stored_sig('REL_CHARGE_ACCOUNT'));
      set_item_result(run_stored_sig('REL_BUDGET_ACCOUNT'));
      set_item_result(run_stored_sig('REL_ACCRUAL_ACCOUNT'));
      set_item_result(run_stored_sig('REL_VARIANCE_ACCOUNT'));
      set_item_result(run_stored_sig('PO REL - MTL_PARAMETERS_VIEW - RELEASE SHIP TO ORG'));
      set_item_result(run_stored_sig('REL-MTL_SUPPLY'));
      set_item_result(run_stored_sig('REL- MTL_SYSTEM_ITEMS_B'));
      set_item_result(run_stored_sig('REL-ZX_LINES'));
      set_item_result(run_stored_sig('REL-ZX_LINES_DET_FACTORS'));
      set_item_result(run_stored_sig('PRC_REL_ZX_REC_NREC_DIST'));
      set_item_result(run_stored_sig('REL-PO_CHANGE_REQUESTS'));
